'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["lt"]={"g-flurpruefung":["Kas įtraukta į vizualinį ir funkcinį patikrinimą prieš pradedant darbą?","Prieš pirmąją dienos misiją.","Patikrinkite tik degalų lygį ir automobilio spalvą.","Patikrinkite stabdžius, vairą, šakes, padangas ir saugos įtaisus pagal naudojimo instrukciją.","Atlikite bandomąjį važiavimą su pakelta apkrova.","Kasdieninė patikra apima saugai svarbias dalis ir funkcijas pagal naudojimo instrukciją."],"g-rueckhalt":["Kaip elgiatės su esama vairuotojo tvirtinimo sistema?","Šakinis krautuvas turi privalomą sulaikymo sistemą.","Naudokite jį tinkamai vairuodami.","Naudokite tik ant nelygių grindų.","Išjunkite jį trumpoms kelionėms.","Numatytos suvaržymo sistemos turi būti naudojamos pagal gamintojo instrukcijas; jie suteikia ypatingą apsaugą apsivertimo atveju."],"g-mangelmelden":["Kas taikoma šakiniam krautuvui su pažeista šakia?","Patikrinę pastebite aiškiai išlinkusį noragą.","Jei įmanoma, paskirstykite apkrovą kitam noragui.","Iki kito aptarnavimo važiuokite tik nedideliais kroviniais.","Nenaudokite šakinio krautuvo ir praneškite apie gedimą atsakingam asmeniui.","Pažeista krovinių kėlimo įranga gali sugesti; Su sauga susijusius defektus reikia išjungti, kol bus išaiškintas."],"g-einweisung":["Perjungiate į šakinį krautuvą su skirtingais valdikliais. Ko reikia prieš naudojant?","Operacija skiriasi nuo ankstesnio automobilio.","Su įrenginiu susijusios instrukcijos ir naudojimo instrukcijos laikymasis.","Visada pakanka trumpo neįsitraukusio kolegos paaiškinimo.","Jei turite šakinio krautuvo licenciją, papildomos informacijos nėra.","Bendroji kvalifikacija nepakeičia būtinos instrukcijos apie faktiškai naudojamą įrenginį."],"g-anbaugeraet":["Turėtumėte naudoti priedą. Ką pirmiausia patikrinsi?","Nauja įranga keičia krovinio paėmimo būdą.","Ar priedas atitinka transporto priemonės patvirtinimą ir leistiną apkrovą.","Tik ar prietaisą galima pritvirtinti vizualiai.","Ar priedas gali būti sumontuotas be dokumentų.","Priedai gali pakeisti likusią keliamąją galią ir apkrovos centrą; Turi būti patikrinti patvirtinimai ir informacija apie keliamąją galią."],"g-diagramm":["Kodėl jums reikia apkrovos diagramos?","Sunkus krovinys, kurio svorio centras yra toli į išorę.","Norėdami nustatyti trumpiausią maršrutą.","Įvertinti didžiausią leistiną apkrovą, priklausomai nuo kėlimo aukščio ir krovinio centro.","Norėdami nustatyti bako talpą.","Leistinos apkrovos, be kita ko, priklauso nuo krovinio centro atstumo ir kėlimo aukščio."],"g-lastschwerpunkt":["Kas paprastai atsitinka, kai svorio centras pasislenka į priekį?","Ilgas krovinys išsikiša toli prieš šakes.","Leidžiama apkrova gali sumažėti.","Keliamoji galia nuolat didėja.","Atstumas neturi įtakos apsivertimo momentui.","Didesnis atstumas nuo apkrovos centro padidina apvertimo momentą ir gali sumažinti leistiną keliamąją galią."],"g-gabelabstand":["Kaip šakės turėtų paimti tinkamą padėklą?","Norite pasiimti tolygiai pakrautą padėklą.","Su noragais kuo arčiau ir tik viename kampe.","Su tokiu dideliu atstumu, kad padėklas apvirsta į šoną.","Su tinkamu atstumu tarp noragų ir pakankamu važiuoklės bei atramos plotu.","Krovinys turi būti patikimai ir kuo tolygiau atremtas ant šakių."],"g-schieflast":["Nestabiliai sukrautas krovinys. Kas yra teisinga?","Pakėlus kartonines dėžes gali nukristi.","Pradėkite lėtai; krūvis stabilizuojasi pats.","Prieš paimdami krovinį, jį pakankamai pritvirtinkite arba leiskite jį surinkti.","Pakelkite krovinį virš galvos aukščio, kad jis netrukdytų.","Laisvas arba nestabilus krovinys gali nukristi ir sukelti pavojų žmonėms; pirmiausia imkitės saugos priemonių."],"g-personen":["Ar galima žmogų pakelti ant įprastų šakių?","Kolega nori pasiekti šviesą.","Taip, jei kolega dėvi šalmą.","Ne, žmonės gali naudotis tik tam skirtomis ir leidžiamomis patalpomis pagal specialius reikalavimus.","Taip, jei tik artėjama prie nedidelio aukščio.","Įprastos šakės nėra asmeninė darbo platforma; Žmonių transportavimui ir kėlimui taikomi specialūs reikalavimai."],"g-transporthoehe":["Kaip dažniausiai transportuojate padėklą?","Kelias skaidrus ir lygus.","Pakeliant krovinį tik tiek, kiek būtina ir laikantis naudojimo instrukcijos.","Pakėlus krovinį kuo aukščiau, kad būtų geriau matomas.","Kai kėlimo stiebas yra stipriai pakreiptas į priekį, nepaisant krovinio.","Žema transportavimo padėtis sumažina apvirtimo ir susidūrimo riziką; Įrenginio instrukcijos yra lemiamos."],"g-kurvenfahrt":["Kodėl greitas posūkis su šakiniu krautuvu pavojingas?","Norite greitai išvažiuoti iš siauro tako.","Nes tik greičiau išsikrauna baterija.","Nes šakinis krautuvas automatiškai vairuoja geriau.","Kadangi šoninės jėgos veikia stabilumą ir gali apvirsti.","Posūkiuose veikia papildomos jėgos; greitis turi būti pritaikytas prie apkrovos ir sąlygų."],"g-ladebruecke":["Ką tikrinate prieš važiuodami ant pakrovimo tilto?","Turėtumėte važiuoti sunkvežimiu.","Tik ar kelias atrodo pakankamai platus.","Keliamoji galia, patikima atrama ir apsauga nuo perjungimo bei transporto priemonės tvirtinimas.","Tik ar įjungtas apšvietimas.","Pakrovimo tiltai ir transporto priemonės turi būti apsaugoti nuo judėjimo ir tinkami kroviniui."],"g-fussgaenger":["Kaip elgiatės painioje sankryžoje su pėsčiaisiais?","Vizualiniai ryšiai apriboti.","Važiuokite tinkamu greičiu, jei reikia, sustokite ir užtikrinkite saugų matomumą.","Veždami krovinį visada reikalaukite pirmumo teisės.","Tiesiog pagirk ir važiuok toliau.","Pėstieji turi specialių apsaugos poreikių; Greitis, matomumas ir susisiekimas turi būti pritaikyti prie eismo maršruto."],"g-batterieladen":["Į ką reikėtų atkreipti ypatingą dėmesį kraunant disko akumuliatorių?","Naudojama akumuliatoriaus įkrovimo stotelė.","Įkrovimo vietą galima pasirinkti nepriklausomai nuo gamintojo nurodymų.","Atvira liepsna leidžiama tol, kol krautuvas stovi.","Tinkama pakrovimo zona, pakankama ventiliacija ir gamintojo specifikacijos, taip pat apsauga nuo gaisro ir sprogimo.","Įkraunant pavojų gali kilti elektros energija, dujos ir cheminės medžiagos; turi būti laikomasi numatytų apsaugos priemonių."],"h-beauftragt":["Kokiomis sąlygomis jums leidžiama savarankiškai valdyti darbo kėlimo platformą?","Turėtumėte naudoti darbo platformą įmonėje.","Jei turite automobilio vairuotojo pažymėjimą.","Jei esate tinkamas, instruktuotas arba kvalifikuotas ir darbdavio įsakytas.","Jei kada nors matėte darbo platformą.","Darbdavys turi užtikrinti tinkamumą, kvalifikaciją ir užduotis pagal veiklos reikalavimus."],"h-vorpruefung":["Ką reikia patikrinti prieš pradedant dirbti su kėlimo platforma?","Naktį scena buvo lauke.","Vizualus ir funkcinis bandymas pagal gamintojo instrukcijas, įskaitant saugos įtaisus.","Tiesiog scenos spalva ir amžius.","Ar darbo medžiaga jau yra platformoje.","Prieš naudojant mašiną, valdiklius, avarines funkcijas ir matomus pažeidimus reikia patikrinti pagal naudojimo instrukciją."],"h-tragfaehigkeit":["Kokia informacija lemia leistiną darbo krepšelio apkrovą?","Du žmonės norėtų su savimi pasiimti papildomų įrankių.","Žmonės gali laisvai įvertinti leistiną bendrą svorį.","Skaičiuojamas tik sunkiausio žmogaus svoris.","Negalima viršyti žmonių, įrankių ir medžiagų keliamosios galios specifikacijų.","Nominali apkrova reiškia bendrą leistiną apkrovą, įskaitant visas vežamas medžiagas."],"h-untergrund":["Į ką atsižvelgi prieš statydamas sceną su atramomis?","Dirbate šalia užpildytos srities.","Tik strėlės pasiekiamoje vietoje.","Patikrinkite požeminio paviršiaus laikomąją galią ir lygumą bei tinkamą atramą pagal instrukcijas.","Ant kuo mažiau išplėstų atramų.","Nepakankamas įžeminimas arba netinkama atrama gali prarasti stabilumą."],"h-wind":["Pučia stiprus vėjas. Kaip jums sekasi?","Atsiduriate su lauko scena.","Laikykitės gamintojo nustatytų ribų ir, jei jos viršytos, sustabdykite veikimą arba saugiai nuleiskite krepšį.","Išplėskite platformą kiek įmanoma, kad ji būtų stabilesnė.","Reaguokite tik tada, kai nukrenta palaidi daiktai.","Gamintojo leidžiamos vėjo sąlygos yra naudojimo ribos; Vėjas gali sukurti pavojingų papildomų jėgų."],"h-strom":["Turite dirbti šalia oro linijos. Kas yra lemiama?","Darbo zonoje yra gyva linija.","Šalmas pakeičia saugaus atstumo laikymąsi.","Tiesiog izoliuokite krepšį ir dirbkite nekoordinuodami.","Išsiaiškinkite pavojingą zoną ir užtikrinkite reikiamus apsauginius atstumus ar kitas tinkamas priemones.","Elektrinis blyksnis galimas ir be tiesioginio kontakto; Prieš pradedant operaciją turi būti nustatytos būtinos apsaugos priemonės."],"h-notablass":["Kodėl reikia žinoti avarinio nuleidimo procedūrą?","Galimas įprastos valdymo sistemos gedimas.","Kad gedimo atveju būtų galima saugiai išsigelbėti pagal įrenginį.","Kad prietaisas veiktų greičiau normaliai veikiant.","Norėdami pakeisti įprastą testavimą.","Avarinės valdymo priemonės, avarinio nuleidimo ir gelbėjimo koncepcijos turi būti žinomos ir veikiančios prieš naudojant."],"h-gelaender":["Kaip pasiekti papildomą aukštį darbo krepšyje?","Montažo taškas jums nepasiekiamas.","Užlipkite ant krepšio tvoros.","Padėkite lentą ant turėklų.","Naudokite tinkamą platformą su pakankamu darbiniu aukščiu; nelipk ant turėklų.","Lipimas ant tvoros ar improvizuotų paaukštinimų kelia pavojų apsaugai nuo kritimo."],"h-psaga":["Kokie reikalavimai taikomi asmeninėms apsaugos nuo kritimo priemonėms?","Naudojate darbo platformą, kuriai yra numatyta suvaržymo sistema.","Visada pakanka bet kokio tvirtinimo taško už krepšio.","Laikykitės rizikos įvertinimo, gamintojo nurodymų ir tinkamų tvirtinimo taškų.","Nenaudokite jokių apsaugos priemonių, jei krepšelis turi turėklus.","Ar ir kokios AAP reikalingos, lemia rizikos įvertinimas, scenos konstrukcijos ir eksploatavimo instrukcijos."],"h-verfahren":["Ar sceną galima perkelti su pakelta platforma?","Darbo vieta yra už kelių metrų.","Tik jei modelis ir eksploatavimo sąlygos tai leidžia pagal gamintojo instrukcijas.","Visada, kol visi laikosi.","Ne, niekada, nepaisant dizaino ir gamintojo patvirtinimo.","Judėjimas pakeltoje padėtyje priklauso nuo įrenginio ir leidžiamas tik patvirtintomis eksploatavimo sąlygomis."],"h-kollision":["Ką reikia organizuoti dirbant šalia kranų ar kitų mašinų?","Judančios dalys gali pasiekti darbo krepšį.","Nieko; darbo krepšelis visada matomas.","Visada važiuokite darbo krepšiu virš kitų mašinų.","Koordinuokite darbo vietas, kad išvengtumėte susidūrimų ar suspaudimo taškų.","Vienalaikis mašinos veikimas reikalauja koordinuotų darbo procesų ir apsaugos nuo susidūrimų ar užstrigimo."],"h-einstieg":["Kaip įeinate ar paliekate darbo krepšelį?","Krepšelį pasieksite žemės lygyje.","Perlipkite per išorinį turėklą.","Per numatytą prieigą saugioje vietoje pagal naudojimo instrukciją.","Per kopėčias, pastatytas šalia jos ištiesus strėlę.","Turi būti laikomasi numatytos prieigos ir gamintojo nurodymų; Nekontroliuojamas lipimas kelia pavojų nukristi."],"h-defekt":["Avarinio sustabdymo priemonė neveikia. ka tu darai?","Apžiūros metu pastebėsite defektą.","Nenaudokite platformos ir praneškite apie defektą.","Tęskite darbą, jei veikia įprasti valdikliai.","Užklijuokite jungiklį, kad niekas jo neveiktų.","Apsaugos įtaiso gedimas yra su sauga susijęs defektas, kuris neleidžia saugiai eksploatuoti."],"h-sicht":["Važiavimo judesio nematyti dėl kliūties. Kaip jums sekasi?","Turėtumėte perkelti mobilią sceną.","Važiuokite lėtai be matomumo.","Tiesiog pasikliaukite atstumo indikatoriumi.","Sustabdykite judėjimą ir užtikrinkite matomumą arba saugius nurodymus pagal naudojimo instrukciją.","Prieš procedūrą būtina saugiai apžiūrėti žmones, kliūtis ir eismo maršrutus."],"h-rettung":["Ką apima diegimo planavimas dirbant didesniame aukštyje?","Scena naudojama atokioje vietovėje.","Tik numatyta darbo trukmė.","Tinkama gelbėjimo koncepcija su prieinamais, apmokytais žmonėmis ir avarinio nuleidimo procedūromis.","Prielaida, kad gaisrinė išspręs bet kokią problemą nedelsiant.","Veiksmingas gelbėjimas turi būti organizuojamas iš anksto, net jei įprastos valdymo priemonės nepavyksta."],"k-befaehigung":["Ko reikia norint savarankiškai valdyti kraną?","Naujas darbuotojas turėtų perimti krano darbus.","Tinkamumas ir reikalaujama kvalifikacija, instruktažas ir atitinkama užduotis.","Pakanka automobilio vairavimo pažymėjimo.","Vieną kartą pažiūrėti užtenka.","Darbai kranu gali būti pavesti tik kvalifikuotiems ir įgaliotiems asmenims; Įrangos instrukcija yra jos dalis."],"k-funktionspruefung":["Ko reikia norint patikrinti kraną prieš pradedant pamainą?","Jūs perimate patalpų kraną.","Tiesiog perskaitykite veikimo laiką vardinėje plokštelėje.","Patikrinkite saugai svarbias funkcijas ir matomus defektus pagal naudojimo instrukciją.","Netikrindami patikrinkite kraną su didžiausia apkrova.","Privaloma eksploatavimo kontrolė padeda ankstyvoje stadijoje nustatyti pavojingus defektus."],"k-traglast":["Kokią reikšmę turi leistina apkrova?","Reikia pakelti krovinį.","Tai neįpareigojanti rekomendacija.","Tai taikoma tik tada, kai kablys yra visiškai įtrauktas.","Negalima viršyti leistinos apkrovos atitinkamoms eksploatavimo sąlygoms.","Leidžiamos apkrovos tam tikrų tipų kranams gali priklausyti nuo spindulio, strėlės padėties ir ginkluotės."],"k-personen":["Kas taikoma žmonėms, kuriems yra kabantys kroviniai?","Krovinys perkeliamas per darbo vietą.","Pavojaus zona turi būti laisva; niekam neleidžiama lįsti po kabančiu kroviniu.","Šalmas leidžia likti tiesiai po juo.","Trumpi kirtimai leidžiami, jei kranas juda lėtai.","Pakabinami kroviniai kelia pavojų nukristi ir susispausti; Žmones reikia saugoti nuo pavojingos zonos."],"k-signale":["Jūs nematote užpuoliko ir gaunate prieštaringus signalus. ka tu darai?","Bendravimas neaiškus.","Tęskite paskutinę disko komandą.","Sustabdykite judėjimą ir aiškiai paaiškinkite bendravimą.","Padėkite krovinį greičiau, nepasitarę.","Saugus krovinio judėjimas reikalauja aiškių signalų ir aiškaus ryšio."],"k-sicht":["Kas suteiks pagalbą transportuojant, jei krano operatorius nemato iki galo krovinio kelio?","Prieškambario stulpas užstoja taką.","Žmogus, kuris praeina pro šalį be išankstinio susitarimo.","Niekas; svarbu tik kabliukas.","Tinkamas, instruktuotas asmuo su aiškiai sutartu supratimu.","Jei apkrovos kelio nesimato, reikia atitinkamos instrukcijos ar kito saugaus sprendimo."],"k-ruck":["Kodėl reikėtų vengti trūkčiojančių krano judesių?","Pradeda siūbuoti didelis krūvis.","Jie sukuria papildomus dinaminius įtempius ir gali destabilizuoti apkrovą.","Jie iš esmės sumažina bet kokį švytuoklės judėjimą.","Jie visada padidina vardinę apkrovą.","Pagreičio ir stabdymo jėgos padidina krano ir stropų apkrovą."],"k-sperrbereich":["Ką reikėtų patikrinti prieš siūbuojant krovinį bendroje erdvėje?","Kiti darbuotojai dirba šalia.","Ar krovinys vizualiai atitinka kraną.","Ar pavojaus zona yra apsaugota ir ar nekyla pavojus žmonėms.","Ar krovinys gali būti nešamas kuo aukščiau virš visų.","Sukamuosiuose ir krovinio keliuose neturi būti neapsaugotų žmonių."],"k-stuetzen":["Kas yra svarbiausia mobiliajam kranui su atramomis?","Ant iš dalies užpildytos žemės statomas kranas.","Tik kelio pločio.","Atraminių plokščių spalva.","Laikantis pagrindas, taip pat atrama ir apkrovos paskirstymas pagal montavimo ir gamintojo instrukcijas.","Įrengimas turi didelę įtaką stabilumui, ypač kintančiomis žemės sąlygomis."],"k-wetter":["Dėl vėjo gūsio krovinys smarkiai siūbuoja. Kas yra teisinga?","Dirbate lauke.","Saugiai sustabdykite judėjimą ir laikykitės leistinų eksploatavimo sąlygų.","Greitai paspartinkite judėjimą.","Ir toliau kelkite krovinį, nepaisant gamintojo nustatytų ribų viršijimo.","Vėjas ir siūbuojantys judesiai gali destabilizuoti krovinį ir kraną; Turi būti laikomasi taikymo apribojimų."],"k-freileitung":["Kas taikoma naudojant kranus šalia oro linijų?","Strėlė arba krovinys gali priartėti prie linijos.","Esant nelaidžiai apkrovai, tarpai nėra svarbūs.","Prieš pradėdami darbą, su atsakingais asmenimis išsiaiškinkite pavojingą zoną ir būtinas apsaugos priemones.","Pasikliaukite tik paties krano operatoriaus reakcija.","Kyla pavojai dėl kontakto ir įtampos svyravimų; būtini saugūs apsauginiai atstumai ar kitos priemonės."],"k-sichern":["Ką darote prieš palikdami kraną?","Darbas nutrūksta.","Leiskite kroviniui pakabinti.","Palikite kraną be priežiūros, kai pavara veikia.","Saugiai nuleiskite krovinį ir pritvirtinkite kraną pagal naudojimo instrukciją.","Pakabinami kroviniai neturi būti nekontroliuojami; Kranas ir krovinys turi būti saugiai pastatyti."],"k-lastanschlag":["Kaip sužinoti, ar naudojamas diržas yra tinkamas?","Krovinį reikia pakelti naudojant kėlimo diržą.","Kalbant apie ženklinimą, keliamąją galią, būklę ir tinkamumą tvirtinimo tipui.","Tik pagal kėlimo dirželio spalvą.","Nes jis jau buvo naudojamas vakar.","Keliamoji galia ir būklė turi būti pakankama, atsižvelgiant į tvirtinimo sąlygas."],"k-stopp":["Žmogus netikėtai patenka į apkrovos kelią. ka tu darai?","Šiuo metu kranas perkelia krovinį.","Nedelsdami saugiai sustabdykite judėjimą ir išvalykite pavojingą zoną.","Tiesiog duokite įspėjamąjį signalą ir toliau važiuokite.","Pakelkite krovinį aukščiau ir važiuokite per jį.","Žmonės turi būti apsaugoti nuo krovinio judėjimo; Jei yra tiesioginis pavojus, judėjimas turi būti sustabdytas."],"k-neuerkran":["Jūs gausite kraną su nežinomu valdymu. Kas yra teisinga?","Valdikliai kitokie nei anksčiau.","Jei įtariate, išbandykite įprastus klavišus.","Leiskite kam nors kitam be mokymosi važiuoti į priekį.","Prieš naudodami savarankiškai, gaukite reikiamas su įrenginiu susijusias instrukcijas.","Net ir patyrusiems kranų operatoriams reikia žinių apie konkrečius naudojamus valdiklius, apsauginius įtaisus ir ribas."],"a-kennzeichnung":["Kaip sužinoti leistiną stropo keliamąją galią?","Norite pasirinkti stropą.","Medžiagos kvapas.","Ant atitinkamo, įskaitomo apkrovos ženklo ir gamintojo informacijos.","Dėl saugojimo trukmės.","Leidžiama apkrova nustatoma pagal ženklinimą ir eksploatavimo sąlygas."],"a-sichtpruefung":["Kėlimo dirže pastebite aiškų pjūvį. Kaip jums sekasi?","Juosta turėtų nešti krovinį.","Nenaudokite juostos ir nesiųskite jos išbandyti arba atmesti.","Uždenkite pjūvį juostele.","Naudokite jį tik ypač mažoms apkrovoms.","Pažeisti tekstiliniai stropai gali sugesti ir turi būti įvertinti pagal išmetimo kriterijus."],"a-neigungswinkel":["Kas atsitiks, jei stropų sruogų pasvirimo kampas yra didesnis nei vertikalus?","Dviejų krypčių kabykla išsiskleidžia labiau.","Sruogų jėgos visada mažėja.","Sruogų jėgos išlieka tos pačios.","Jėgos sruogose didėja; Turi būti laikomasi leistinų kampų ir keliamosios galios.","Didėjant plitimui, didėja kiekvienos atraminės gijos tempimo jėga."],"a-schwerpunkt":["Kodėl reikia žinoti krovinio svorio centrą?","Krovinys pastatytas netolygiai.","Kad krovinys keliamas išliktų stabilus ir nevaldomai neapvirstų.","Norėdami pasirinkti stropų spalvą.","Kad būtų galima greičiau pasukti krovinį.","Nepalankūs tvirtinimo taškai arba svorio centro padėtis gali lemti apvirtimą, paslydimą ar šlaitus."],"a-kantenschutz":["Kėlimo diržas priglunda prie aštraus komponento krašto. Ką reikėtų daryti?","Komponentas turi būti pakeltas.","Greitai pakelkite krovinį, kol nepažeidžiamas diržas.","Naudokite tinkamą krašto apsaugą ir patikrinkite tvirtinimo tipą.","Pakrovimo paviršių valykite tik šluoste.","Aštrūs kraštai gali pažeisti atraminius pluoštus; pakabinimo įranga turi būti atitinkamai apsaugota."],"a-haken":["Į ką atkreipiate dėmesį, kai tvirtinate stropą?","Naudojate krovinio kabliuką.","Uždėkite diržą ant kablio galiuko šono.","Laikykite apsauginį dangtelį atidarytą visam laikui.","Įdėkite kabliuką į kablio pagrindą taip, kaip numatyta, ir laikykitės saugos įtaisų.","Neleistina apkrova ant kablio galiuko ir tvirtinimo trūkumas gali lemti, kad jis gali būti atkabintas."],"a-knoten":["Ar galite sutrumpinti per ilgą kėlimo diržą su mazgu?","Stotelės ilgis netinka.","Ne; Naudokite tik tinkamo tipo stropus arba tinkamą stropavimo įrangą.","Taip, jei mazgas traukiamas labai stipriai.","Taip, kol krovinys šiuo metu stovi.","Mazgai gali žymiai susilpninti tekstilinius stropus ir neleidžiama improvizuoto ilgio reguliavimo."],"a-probehub":["Kodėl krovinys iš pradžių keliamas atsargiai?","Norite saugiai transportuoti.","Kad ji galėtų kuo greičiau keliauti į darbą ir atgal.","Norėdami patikrinti stropų padėtį, stabilumą ir svorio centrą.","Kadangi apkrova didėja automatiškai.","Valdomas pirmasis smūgis padeda aptikti neteisingus sustojimus ir nestabilias krovinio padėtis."],"a-lastweg":["Kur žmonėms leidžiama apsistoti, kol vežamas krovinys?","Krovinys perkeliamas kranu.","Tiesiogiai po kroviniu su apsauginiu šalmu.","Ant naštos, jei jie gali išsilaikyti.","Už pavojaus zonos ribų ir ne po kabančiu kroviniu.","Net ir kruopščiai pritvirtinus, vis tiek kyla pavojus, kad krovinys nukrenta arba siūbuoja."],"a-haende":["Kaip išvengti suspaudimo traumų nujunkymo metu?","Krovinys artėja prie atraminio paviršiaus.","Rankas ir kojas laikykite atokiau nuo gniuždymo zonos ir naudokite tinkamas priemones.","Laikykite krovinį plika ranka.","Atsistokite tarp krovinio ir sienos, kad ištaisytumėte padėtį.","Tarp krovinio ir atramos susidaro pavojingi suspaudimo taškai."],"a-vierstraenge":["Kas taikoma apkrovos paskirstymui keturkoje pakaboje be apkrovos kompensavimo?","Tvirtinama standi apkrova.","Visos keturios sruogos neišvengiamai turi tą patį kiekį.","Neturint vienodo pasiskirstymo įrodymo, keturių vienodai apkrautų gijų laikomoji galia negali būti naudojama kaip bendras įvertinimas.","Tada pasvirimo kampas nėra svarbus.","Nevienodas sruogų apkrovimas galimas esant standžioms apkrovoms; Į tai reikia atsižvelgti nustatant projektą ir leistiną apkrovą."],"a-chemikalien":["Kas taikoma naudojant tekstilinius stropus, kurie liečiasi su cheminėmis medžiagomis?","Dirbate su nežinomu skysčiu.","Juostos spalva patikimai parodo jos patvarumą.","Kiekviena tekstilinė juosta yra atspari visoms cheminėms medžiagoms.","Patikrinkite ilgaamžiškumą ir gamintojo informaciją; Nenaudokite netinkamų priemonių.","Cheminės medžiagos gali atakuoti stropus ir nepastebimai sumažinti jų laikomąją galią."],"a-aufbewahrung":["Kaip stropai laikomi po naudojimo?","Misija baigta.","Išvalykite, išdžiovinkite ir apsaugokite nuo pažeidimų pagal gamintojo specifikacijas.","Įstrigo ant žemės po neapsaugotu kroviniu.","Ant bet kokio aštraus lauko kabliuko.","Tinkamas sandėliavimas apsaugo nuo ankstyvo nusidėvėjimo ir palengvina vizualinį patikrinimą."],"a-auswahl":["Į ką reikėtų atkreipti ypatingą dėmesį, kai susiduriate su jautriais ar aštriais kraštais kroviniais?","Dažytas mašinos komponentas turi būti perkeltas.","Tik transportavimo greitis.","Tinkami stropai ir apsauginės priemonės krovinio paviršiui ir kraštams.","Nepriklausomai nuo apkrovos, visada tas pats plieninis trosas.","Priedo tipas ir medžiaga turi atitikti geometriją, paviršių ir pavojų."],"a-abstimmung":["Krano operatorius nemato jūsų. Kaip duodate nurodymus?","Esate paskirtas kaip užpuolikas.","Mojuojate savo nuožiūra, kol prasideda judėjimas.","Jums tereikia paskambinti ir išeiti.","Per aiškiai sutartus ženklus ar kitą patikimą komunikaciją.","Užpuolikai ir kranų operatoriai turi aiškiai bendrauti; Jei neaišku, judėjimas turi būti sustabdytas."],"b-qualifikation":["Ko reikia žmogui, norint saugiai eksploatuoti hidraulinį ekskavatorių eksploatacijos metu?","Darbus statybvietėje turėtų perimti naujas žmogus.","Atitinkama kvalifikacija, su įrenginiu susiję instruktažai ir reikalaujama užduotis.","Tik automobilio vairavimo pazymejimas.","Tiesiog greitas operacijos stebėjimas.","Darbdavys turi užtikrinti reikiamą kvalifikaciją ir tinkamai instruktuoti operatorių užduočiai atlikti."],"b-pruefung":["Kas įtraukta į kasdienę mašinos patikrą?","Jūs perimate ekskavatorių.","Patikrinkite dažų spalvą ir sėdynės apmušalus.","Vizuali apžiūra ir veikimo bandymai pagal naudojimo instrukciją, pavyzdžiui, ar nėra nuotėkio ir pažeidimų.","Judinkite strėlę visu greičiu, kol ji sustos.","Hidraulinės sistemos, važiuoklės ir saugos įtaisų pažeidimai gali sukelti rimtų nelaimingų atsitikimų."],"b-leitungen":["Ką reikia žinoti apie požeminius vamzdžius prieš kasant?","Reikėtų kasti griovį.","Tik apytikslis planuojamos kasimo duobės gylis.","Pakanka antžeminių ženklų spalvos.","Išsiaiškinkite galimų linijų vietą ir nustatykite tinkamas saugumo ir žvalgymo priemones.","Pažeisti elektros, dujų ar vandens vamzdžiai gali turėti gyvybei pavojingų pasekmių."],"b-schwenkbereich":["Kaip apsaugoti žmones ekskavatoriaus sūpynių zonoje?","Jūs renkate medžiagą su strėle.","Aptverkite arba apsaugokite pavojingą zoną ir saugokite nuo žmonių.","Prieš pasukdami, lėtai judinkite kastuvą.","Važiuokite per teritoriją virš galvų.","Pasukamas antstatas ir darbo įranga kelia suspaudimo ir smūgio pavojų."],"b-boeschung":["Kas svarbu dirbant šalia kasimo duobės krašto?","Ekskavatorius stovi ant nustatytos arba užpildytos žemės.","Vien nuo kasimo gylio priklauso leistina vieta.","Atkreipkite dėmesį į krašto keliamąją galią ir tvirtinimą bei reikiamus atstumus pagal rizikos vertinimą.","Važiuokite kuo arčiau krašto, kad sutaupytumėte atstumą.","Jei nėra pakankamai laisvos vietos arba stabilus gruntas, pylimas gali sugesti ir mašina nukristi."],"b-standsicherheit":["Kodėl nuolydis ir žemė yra labai svarbūs naudojimui?","Statybos aikštelė yra ant šlaito.","Mašina vienodai stabili ant bet kokio paviršiaus.","Vikšrinės važiuoklės pašalina bet kokią apvirtimo riziką.","Nelygumai ir nuolydžiai gali turėti įtakos stabilumui; Laikykitės taikymo ribų.","Stabilumas ir apsivertimo sauga priklauso nuo grindų, įrangos, krovinio ir mašinos padėties."],"b-wechselgeraet":["Ką tikrinate pakeitę ekskavatoriaus kaušą naudodami greitąją jungtį?","Buvo įdiegtas naujas priedas.","Ar jis tinkamai užrakintas ir pritvirtintas pagal naudojimo instrukciją.","Tik ar sutampa kastuvo spalva.","Ar hidraulika veikia kuo tyliau.","Dėl netinkamų spynų priedai gali nukristi."],"b-heben":["Į ką reikėtų atkreipti dėmesį keldami laisvai kabantį krovinį ekskavatoriumi?","Ekskavatorius naudojamas kėlimo darbams.","Tik įprasta kasimo jėga yra lemiama.","Laikykitės leistinos kėlimo apkrovos, tinkamų tvirtinimo taškų ir nurodytų apsauginių įtaisų.","Krovinį galima užkabinti ant kaušo dantų.","Kėlimas leidžiamas tik numatytomis darbo sąlygomis su tinkama įranga."],"b-rueckwaerts":["Turite pasukti atgal, bet nematote kelio. Kas yra teisinga?","Netoliese yra kiti darbininkai.","Atsargiai važiuokite be matomumo.","Tiesiog pagirk ir važiuok toliau.","Sustokite, užtikrinkite matomumą ir pavojingą zoną arba organizuokite atitinkamas instrukcijas.","Važiuojant atbuline eiga neturi kelti pavojaus žmonėms; ribotam matomumui reikia papildomų priemonių."],"b-kabel":["Strėlė gali priartėti prie oro linijos. ka tu darai?","Dirbate ankštoje statybų aikštelėje.","Iš anksto su atsakingais asmenimis išsiaiškinkite pavojingą zoną ir tinkamas apsaugos priemones.","Ignoruokite liniją, jei strėlė nudažyta.","Tik ypač greitai judinkite strėlę.","Elektros pavojai kyla dėl kontakto ir sprogimo; būtini saugūs atstumai ir apsaugos priemonės."],"b-verlassen":["Kaip pastatyti ekskavatorių prieš išvykstant?","Jūs darote pertrauką.","Palikite strėlę laisvai plaukioti.","Saugiai pastatykite darbo įrangą ir apsaugokite ją nuo judėjimo ir neleistino naudojimo.","Palikite veikiantį variklį ir atidarytą kabiną.","Nuleistos darbo priemonės ir apsauga nuo netyčinio judėjimo sumažina nelaimingų atsitikimų riziką."],"b-hydraulik":["Ant pažeistos linijos pastebite aukšto slėgio hidraulinę alyvą. Kas yra teisinga?","Nuteka linija.","Pajuskite nutekėjimą ranka.","Esant slėgiui, pritvirtinkite naują spaustuką.","Saugiai išjunkite mašiną, leiskite sumažinti slėgį ir pasirūpinkite, kad remontą atliktų įgaliotas specialistas.","Aukšto slėgio hidraulinis skystis gali rimtai susižaloti; niekada netikrinkite, ar nėra nuotėkio ranka."],"b-unterbau":["Koks pavojus važiuojant nestabiliu paviršiumi?","Po lietaus žemė minkšta.","Mašina gali nuskęsti, nuslysti arba apvirsti.","Pavara automatiškai tampa platesnė.","Dėl to sukimosi diapazonas yra saugesnis.","Nepakankama keliamoji galia gali labai pabloginti stabilumą ir važiavimo saugumą."],"b-arbeitsgeraet":["Ar kas nors gali dirbti po pakeltu padargu?","Žmogus nori kažką valdyti po kastuvu.","Taip, kai variklis dirba tuščiąja eiga.","Ne, ne be reikalingos saugios atramos ir darbo įrangos tvirtinimo.","Taip, jei asmuo dėvi apsauginį šalmą.","Hidraulinė įranga gali nuskęsti; Priežiūros darbams atlikti reikalinga saugi darbo įranga."],"b-geraeteart":["Hidraulinį ekskavatorių pereinate prie ratinio krautuvo. Ko reikia?","Veikimas ir judėjimo elgesys skiriasi.","Tiesiog ta pati avalynė.","Bandomasis važiavimas be instrukcijų.","Kvalifikacija arba instrukcija, reikalinga naujam mašinos tipui.","Kvalifikacija turi atitikti naudojamos mašinos tipą ir konkrečius eksploatavimo reikalavimus."],"g-neigung":["Jūs vairuojate pakrautą šakinį krautuvą įkalnėje. Kas svarbu?","Maršrutas turi aiškų nuolydį.","Visada nukreipkite krovinį žemyn, net jei jis sunkus.","Nukreipkite krovinį į kalną ir laikykitės važiavimo įkalnėse nurodymų.","Nepriklausomai nuo važiavimo krypties, pakelkite šakę iki maksimumo.","Įkalnėse ir nusileidimuose krovinys visada turi būti nešamas įkalnėn; Būtina laikytis transporto priemonės ir naudojimo instrukcijų."],"g-gabelabsenken":["Kodėl stovint reikia nuleisti šakę?","Šakinis krautuvas pastatytas pertraukai.","Kad kiti galėtų naudoti šakę lipti aukštyn.","Kad šakutė būtų geriau matoma iš tolo.","Kad krovinio kėlimas nesukeltų nereikalingo pavojaus suklupti ar susižeisti.","Nuleisti krovinio paėmimo įrenginiai sumažina nelaimingų atsitikimų riziką dėl išsikišusių arba nepritvirtintų šakių."],"g-fahrerwechsel":["Kolega norėtų pasiskolinti krautuvą. Kas turi būti?","Kolega turi tik žodinį jūsų leidimą.","Jis turi turėti reikiamą kvalifikaciją ir įmonės mandatą.","Jūsų užduotis automatiškai taikoma ir jam.","Asmeninio automobilio vairuotojo pažymėjimo pakanka bet kokiam verslui.","Nepriklausomas vadovavimas yra susietas su asmeniniu tinkamumu, mokymu, kvalifikacija ir veiklos užduotimis."],"g-ladungssicherung":["Padėkle yra palaidos, sukrautos dėžės. Kas yra teisinga?","Važiuojant gali nukristi kartoninė dėžutė.","Prieš gabendami krovinį apsaugokite, kad jis neslystų ir nenukristų.","Ypač nelygia žeme važiuokite tik lėtai.","Atsilaisvinusias dėžes kompensuokite aukštesne šakės padėtimi.","Krovinys turi būti stabilus ir apsaugotas nuo kritimo prieš vežant jį su krautuvu."],"g-bodenbelastung":["Priešais jus yra antklodė su ribota laikomoji galia. Kaip apsisprendžiate?","Maršrutas veda per tarpinį lygį.","Tiesiog atkreipkite dėmesį į sunkvežimio svorį be krovinio.","Išsiaiškinkite leistiną šakinių krautuvų ir krovinių grindų apkrovą.","Važiuokite su impulsu, kad lubos būtų apkraunamos trumpiau.","Svarbu yra bendras faktinis apkrovos plotas, įskaitant transporto priemonę, apkrovą ir dinamines įtakas."],"g-verkehrswege":["Jūsų kelią kerta pažymėtas pėsčiųjų takas. Kas yra teisinga?","Pėstieji prie perėjos gali patekti bet kuriuo metu.","Jūs visada galite reikalauti pirmenybės su ragu.","Per ženklinimą leidžiama važiuoti nepastebimai.","Sureguliuokite greitį, atkreipkite dėmesį į pėsčiuosius ir toliau važiuokite tik tada, kai kelias laisvas.","Eismo maršrutais turi būti važiuojama atsižvelgiant į žmones; Įspėjamieji ženklai nepakeičia saugaus matomumo ir aiškaus maršruto."],"g-parkbremse":["Pastatote šakinį krautuvą ant lygios žemės. Kas tai apima?","Norite kelioms minutėms palikti vairuotojo vietą.","Pastatykite, įjunkite stovėjimo stabdį ir apsaugokite nuo neleistino naudojimo.","Palikite automobilį tik neutralioje padėtyje.","Šakutę palikite galvos aukštyje, kad niekas jos neliestų.","Prieš išvažiuojant, autokrautuvas turi būti saugiai sustabdytas ir apsaugotas nuo netikėto judėjimo."],"g-typenschild":["Kokia informacija yra privaloma, kai kalbama apie krautuvo krovinį?","Norite pasiimti sunkią mašiną.","Apskaičiuota keliamoji galia, pagrįsta transporto priemonės dydžiu.","Gamintojo informacija apkrovos arba keliamosios galios diagramoje.","Paskutinio vežamo padėklo svoris.","Leidžiama apkrova nustatoma pagal gamintojo informaciją ir, be kita ko, priklauso nuo apkrovos centro ir kėlimo aukščio."],"g-tore":["Prie žemos perėjos privažiuojate šakiniu krautuvu. Ką tu tikrini?","Transporto priemonėje yra didžiulė apkrova.","Ar galima saugiai pravažiuoti, įskaitant krovinį ir pritvirtinimą.","Tik šakės laikiklio aukštis be krovinio.","Nesvarbu, ar galite važiuoti greičiau, kol vartai neužsidaro.","Prieš pravažiavimus reikia atsižvelgti į laisvą aukštį ir plotį, taip pat krovinio ir transporto priemonės matmenis."],"g-reifen":["Kasdienės patikros metu randate stipriai pažeistą padangą. ka tu darai?","Ant padangos matomi su sauga susiję pažeidimai.","Važiuojate lėtai iki reguliarios techninės priežiūros paskyrimo.","Padidinate padangų slėgį ir toliau važiuojate.","Jūs nepriimate automobilio eksploatuoti ir nepranešate apie žalą.","Pažeistos padangos gali pabloginti stabilumą ir pabloginti valdymą; defektas turi būti išaiškintas prieš naudojant."],"h-absperren":["Darbuotojai eina pro jūsų darbo platformą. Ko reikia?","Kyla pavojus nukristi įrankiai.","Tinkama apsauginė arba ribota zona po darbo vieta.","Tiesiog pranešimas, kai pirmą kartą praeinate.","Įrankius laikykite kuo toliau nuo krepšio krašto.","Darbo zona po paaukštintomis darbo vietomis turi būti apsaugota nuo pavojaus dėl krintančių dalių."],"h-werkzeuge":["Kaip gabenate įrankius darbo krepšelyje?","Aukštyje reikia kelių mažų įrankių.","Laisvai padėkite juos ant turėklų, kad būtų lengvai pasiekiami.","Laikykite ir pritvirtinkite taip, kad nenukristų ir netrukdytų darbui.","Pritvirtinkite prie turėklų išorės kišenėje.","Atsilaisvinę daiktai gali nukristi ir sukelti pavojų žmonėms; reikalinga saugi saugykla."],"h-abstuetzung":["Ant šulinio dangčio stovi atrama. Ką reikia patikrinti?","Norite pakelti platformą.","Tiesiog įsitikinkite, kad dangtis yra sausas.","Ar tuo metu apkrova gali būti saugiai absorbuojama.","Ar nereikia naudoti kitų atramų.","Pagrindas ir sąlyčio vietos turi būti pajėgios saugiai sugerti atramines jėgas; Dangteliai turi būti vertinami atskirai."],"h-notaus":["Kada reikia naudoti avarinio stabdymo įtaisą?","Iš karto atsiranda pavojingas judėjimas.","Tik eilinės pamainos pabaigoje.","Sustabdymui esant dideliam pavojui pagal naudojimo instrukciją.","Kaip planuoto nuleidimo pakaitalas.","Avarinis stabdymas naudojamas pavojui išvengti, o ne įprastam valdymui ar normaliam išjungimui."],"h-schraegstellung":["Atsiliepia scenos pakreipimo įspėjimas. kaip tu reaguoji?","Mašina yra ant nuožulnaus paviršiaus.","Nekreipiate dėmesio į įspėjimą esant žemam darbiniam aukščiui.","Nepaisant įspėjimo, važiuojate į aukščiausią kėlimo padėtį.","Sustojate ir pastatote sceną į saugią būklę pagal gamintojo nurodymus.","Pasvirimo įspėjimai gali rodyti nepakankamą stabilumą; tolesni judesiai neturi padidinti pavojaus."],"h-umgebung":["Ką reikia organizuoti įsirengiant šalia eismo zonos?","Transporto priemonės gali liesti sceną.","Apsauga nuo susidūrimų ir tinkamas eismo nurodymas.","Pasukite darbo krepšį kuo toliau virš kelio.","Tik įspėjamasis skambutis prieš paleidžiant.","Kėlimo darbo platformos turi būti apsaugotos nuo susidūrimo su eismo dalyviais; montavimas turi būti atitinkamai apsaugotas."],"h-ueberlast":["Suveikia krepšelio perkrovos įspėjimas. ka tu darai?","Buvo pakviesti papildomų įrankių.","Baigti darbą didesniu greičiu.","Nustatykite leistiną krepšio apkrovą ir laikykitės gamintojo nurodymų.","Visam laikui išjunkite įspėjamąjį signalą.","Negalima viršyti didžiausios leistinos krepšio apkrovos, įskaitant žmones ir medžiagas."],"h-quetschen":["Jūs varote krepšį arti po stogu. Kuris pavojus ypač svarbus?","Virš krepšio liko mažai vietos.","Suspaudimas arba suspaudimas tarp krepšio ir konstrukcijos.","Kad variklis sunaudoja daugiau degalų.","Kad važiavimo kryptis visada pasikeičia automatiškai.","Ankštos erdvės virš arba šalia darbo krepšio gali rimtai susižaloti."],"h-stromausfall":["Scena lieka dideliame aukštyje be pagrindinės pavaros. Kas yra teisinga?","Įprastas krepšelio valdiklis nebereaguoja.","Jūs lipate žemyn nuo strėlės be saugumo.","Jūs laukiate savo pamainos pabaigos nebūdami informuoti.","Pradėkite paruoštą gelbėjimą, naudodami apmokytus žmones ir avarinį nuleidimą.","Saugus gelbėjimas turi būti suplanuotas dėl sutrikimų; Apmokyti žmonės turi žinoti avarines funkcijas."],"h-transportstellung":["Kaip paruošiate sceną transportui?","Kėlimo platforma pakraunama į tinkamą transporto priemonę.","Pagal naudojimo instrukciją nustatykite strėlę ir platformą į transportavimo padėtį.","Pritvirtinkite platformą kuo toliau.","Palikite atramas prailgintas, kad užimtų daugiau vietos.","Numatyta transportavimo padėtis ir krovinio tvirtinimas priklauso nuo gamintojo ir transportavimo specifikacijų."],"k-bremsprobe":["Ką rodo krano stabdžio veikimo patikrinimas prieš naudojimą?","Norite, kad galėtumėte saugiai laikyti krovinį.","Ar stabdys sustoja ir sulaiko judėjimą taip, kaip numatyta.","Tik ar veikia salono apšvietimas.","Ar kabliukas gali automatiškai išlaikyti krovinį.","Prieš naudojant, pagal specifikacijas reikia patikrinti su sauga susijusias funkcijas."],"k-schraegzug":["Ar galite kranu traukti į šoną esantį krovinį kampu?","Kablys nėra vertikaliai virš krovinio.","Taip, jei kranas vis dar turi apkrovos rezervą.","Ne, krovinių negalima traukti naudojant neleistinus įstrižinius traukimus.","Taip, jei stropai ypač trumpi.","Traukimas įstrižai gali sukelti nekontroliuojamus judesius ir papildomą krano bei stropų apkrovą."],"k-verhakt":["Ant pagrindo kabo krovinys. Kas yra teisinga?","Keliant jaučiamas pasipriešinimas.","Keliate tol, kol jis atsitraukia.","Jūs trūkčiodami perkeliate krovinį į šoną.","Jūs sustojate ir saugiai pašalinate tvirtinimą arba blokavimą.","Įstrigusių krovinių negalima atplėšti jėga, nes gali atsirasti nepriimtinos jėgos."],"k-anzuheben":["Ką tikrinate pirmą kartą trumpam keldami pakabintą krovinį?","Krovinys pakyla kelis centimetrus nuo žemės.","Nesvarbu, ar jis kabo pusiausvyroje, o sustojimas yra saugus.","Ar žmogus gali atsidurti tiesiai po krūviu.","Ar kranas tampa stabilesnis greitai sukant.","Trumpas valdomas kėlimas naudojamas norint patikrinti pritvirtinimą, pusiausvyrą ir saugų krovinio elgesį."],"k-lastweg":["Kur turėtų būti krano krovinio transportavimo kelias?","Kelios darbo vietos yra pagal galimą apkrovos kelią.","Jei įmanoma, virš užimtų darbo vietų.","Suplanuotu, aiškiu keliu, kuriame nėra žmonių, kuriems gresia pavojus.","Visada įstrižai per judriausią zoną.","Krovinių maršrutai turi būti organizuojami taip, kad kabantys kroviniai nekeltų pavojaus žmonėms."],"k-signalverlust":["Nutrūksta radijo ryšys su maršalu. ka tu darai?","Nematote paties apkrovos kelio.","Jūs tęsite judesį lėtai.","Eksperimentiškai siūbuojate ankstesne kryptimi.","Sustabdote judėjimą, kol gausite aiškų ir saugų supratimą.","Jei trūksta bendravimo, painus krovinio judėjimas gali nesitęsti."],"k-haken":["Apsauginis kablys neužsidaro patikimai. Kas yra teisinga?","Apžiūros metu pastebimas sugedęs uždarymas.","Prieš naudojimą klaidą reikia ištaisyti profesionaliai.","Užsegimą tvirtai surišate kabelio raiščiu.","Kabliuką naudojate tik lengviems kroviniams.","Dėl sugedusių krovinio kabliukų tvirtinimo įtaisų stropai gali atsikabinti, todėl juos reikia pataisyti."],"k-zugrichtung":["Kas svarbu vertikaliai atlaikant krovinį?","Krovinys turi būti pakeltas iš mašinos.","Krano kablys turi būti išlygintas aukščiau krovinio svorio centro.","Kabliukas turi būti pastatytas kuo į šoną.","Prieš pakeliant krovinį reikia stumti.","Virš apkrovos centro maksimaliai vertikalus jėgos poveikis leidžia išvengti neleistinų šoninių jėgų ir nekontroliuojamo siūbavimo."],"k-wartung":["Ant krano pastebimas neįprastas šlifavimo triukšmas. Kaip jums sekasi?","Triukšmas kyla keliant.","Uždenkite triukšmą didesniu greičiu.","Saugiai sustabdykite operacijas, praneškite apie defektus ir juos pašalinkite.","Tęskite darbą be įspėjimo iki pertraukos.","Pastebimi pokyčiai gali rodyti saugai svarbią žalą ir reikalauti atlikti patikrinimą."],"k-absetzen":["Ką reikia garantuoti nuleidžiant krano krovinį?","Didelis krovinys dedamas ant paviršiaus.","Krovinys gali gulėti nepritvirtintas ant nuožulnaus paviršiaus.","Stropai nuimami jam dar plūduriuojant.","Krovinys yra stabilus ir apsaugotas nuo apvirtimo ar nuriedėjimo.","Krovinys gali būti atleidžiamas nuo stropinės pavaros tik saugiai nustačius ir nusistačius stabilumą."],"l-schwerpunkt":["Kodėl prieš smūgiuojant turi būti žinomas svorio centras?","Turi būti vežama asimetrinės formos mašina.","Kad krovinys keliant išliktų kiek įmanoma subalansuotas.","Kad stropus būtų galima rinktis kokio ilgio.","Kad leistina apkrova nevaidintų vaidmens.","Svorio centro padėtis turi įtakos krovinio pasiskirstymui ir saugiam balansui keliant."],"l-etikett":["Kėlimo diržas neturi įskaitomos keliamosios galios etiketės. Kas yra teisinga?","Žymėjimas tapo neatpažįstamas.","Įvertinkite apkrovą pagal spalvą.","Nenaudokite kėlimo diržo, kol nebus aiškiai įrodytas jo tinkamumas.","Diržą naudokite tik vieną kartą mažiems kroviniams.","Stropams būtinas tinkamas ženklinimas; Nepaaiškinama keliamoji galia neleidžia saugiai pasirinkti."],"l-kantenschutz":["Ant aštraus plieno krašto guli tekstilinė juosta. Ko reikia?","Krovinys turi aštrius kraštus.","Patraukite juostą kuo tvirčiau be apsaugos.","Atlikite smūgį greičiau.","Naudokite tinkamą briaunų apsaugą ar kitą tinkamą pakabinimo įrangą.","Aštrūs kraštai gali pažeisti arba perpjauti tekstilės stropus; reikalinga tinkama apsauga."],"l-spreizwinkel":["Kaip didesnis pasvirimo kampas veikia stropų apkrovą?","Krovinys keliamas dviem nuožulniais lynais.","Esant mažiau palankiems kampams, jėgos gijose gali padidėti.","Sruogų jėgos išnyksta.","Kampas neturi įtakos įtempimui.","Esant mažiau palankiam sustojimo kampui, jėgos vienai sruogai gali padidėti; Būtina laikytis apkrovos lentelių."],"l-knoten":["Ar stropo virvę galima sutrumpinti pagal pageidavimą naudojant mazgą?","Virvė per ilga planuojamai apkrovai.","Taip, tvirtas mazgas pagerina keliamąją galią.","Ne, naudokite tik patvirtintus trumpinimo ir tvirtinimo būdus.","Taip, jei mazgas pritvirtintas juostele.","Neleistini mazgai susilpnina stropus ir keičia jų leistiną apkrovą."],"l-zeichen":["Kas taikoma bendravimui su asmeniu, kuris valdo kraną?","Apkrovos kelias iš dalies uždengtas.","Keli žmonės vienu metu duoda skirtingus signalus.","Naudojami aiškūs, iš anksto sutarti signalai.","Niekada nereikia ryšio su radijo kranais.","Aiškūs ženklai ir aiški atsakomybė užkerta kelią pavojingiems neteisingiems judesiams."],"l-sichtpruefung":["Kada reikia patikrinti, ar stropai neturi matomų defektų?","Norite naudoti stropinę grandinę.","Prieš naudodami atkreipkite dėmesį į bet kokius išoriškai matomus pažeidimus.","Tik jei jau įvyko nelaimė.","Tik vieną kartą perkant pirmą kartą.","Prieš kiekvieną naudojimą turi būti įvertinta saugi darbo būklė; Matoma žala neleidžia saugiai naudoti."],"l-drehung":["Pakeltas krovinys pradeda nevaldomai suktis. ka tu darai?","Krovinys juda krovinio keliu.","Jūs įkišate ranką tarp krovinio ir sienos.","Jūs atsikratote naštos ir jos laikotės.","Jūs laikotės atstumo ir leidžiate judėjimui sustoti kontroliuojamai.","Nekontroliuojami krovinio judesiai sukelia suspaudimo ir smūgio pavojų; Žmonės turi palikti pavojingą zoną."],"l-ablegen":["Kada nuo krovinio galima išimti stropus?","Krovinys dedamas ant estakadų.","Jei krovinys yra stabilus ir apsaugotas nuo apvirtimo ar nuriedėjimo.","Kai tik jis pirmą kartą paliečia žemę, nepaisant jo padėties.","Vis dar skraidydami, kad sutaupytumėte laiko.","Stropus galima nuimti tik saugiai ir stabiliai padėjus."],"l-ketten":["Grandininis stropas turi stipriai sulenktą grandį. ka tu darai?","Pažeidimai matomi dar prieš pakėlimą.","Apvyniokite pažeistą vietą viela.","Nuimkite grandinę nuo naudojimo ir paprašykite ją profesionaliai patikrinti.","Pakelkite krovinį tik perpus aukščiau.","Deformuotos grandinės grandys yra matomi pažeidimai, kurie gali trukdyti saugiai naudoti."],"b-einweiser":["Kas svarbu, kai matomumas nuo ekskavatoriaus yra ribotas?","Dalis pastato užstoja važiavimo zoną.","Atitinkamos vaizdinės priemonės arba nurodymas ir aiškus bendravimas.","Tiesiog stebėkite gaubtą.","Važiuokite per sukimosi sritį, nepaisant to, kad esate nematomas.","Jei matomumas ribojamas, pavojai turi būti užkirsti kelią papildomomis organizacinėmis ir techninėmis priemonėmis."],"b-aushub":["Kur galima laikyti iškastą medžiagą prie statybinės duobės?","Duobės kraštas neturi kelti papildomos rizikos.","Sukraukite tiesiai ant krašto, kad važiuojamieji keliai liktų laisvi.","Laikyti pakankamai saugiu atstumu ir laikantis statybvietės specifikacijų.","Padėkite ant laisvų atramų be tolesnių bandymų.","Iškasta medžiaga dėl papildomų apkrovų gali kelti pavojų pylimams ir atramoms; Turi būti laikomasi saugaus atstumo."],"b-personen":["Ar žmonėms leidžiama likti sūpynių zonoje, kol ekskavatorius juda?","Žmogus nori matuoti slinkdamas.","Taip, kol ji dėvi apsauginį šalmą.","Taip, jei ekskavatorius siūbuoja lėtai.","Ne, prieš judėjimą pavojinga zona turi būti laisva.","Sukimosi srityje kyla rimtų suspaudimų ir susižalojimų pavojus; vieta turi būti laisva."],"b-ladung":["Kaip saugiai transportuoti medžiagą ratiniu krautuvu?","Užpildytu kastuvu reikia pervažiuoti per kiemą.","Tinkama žema transportavimo padėtis ir laisvas kelias.","Su pakeltu kastuvu geresniam matomumui.","Su atviromis durimis ir stipriu vairavimo kampu.","Tinkama transportavimo padėtis sumažina apvirtimo riziką ir pagerina vairavimo stabilumą."],"b-anbaupruefung":["Ką tikrinate prijungę priedą?","Buvo pritvirtintas naujas kastuvas.","Tik dažų švara.","Saugus užrakinimas ir veikimas pagal naudojimo instrukciją.","Tik ar prietaisas iš išorės atrodo taip pat.","Neteisingi greitųjų jungčių užraktai gali netyčia atleisti priedus."],"b-einstieg":["Kaip saugiai patekti į ekskavatoriaus kabiną?","Po lietaus laipteliai purvini.","Įlipkite į kabiną per strėlę.","Užlipkite ant vikšrų vienu šuoliu.","Naudokite nurodytus laiptelius ir rankenas ir nuvalykite nešvarius laiptelius.","Tinkami pakilimai ir saugūs laikymosi taškai sumažina paslydimo ir nukritimo riziką."],"b-graben":["Tranšėjos sienoje matomi įtrūkimai ir ji byra. Kas yra teisinga?","Dirbate prie pat griovio.","Nutraukite darbą ir pasirūpinkite, kad atsakingi asmenys apsaugotų kasimo duobę.","Norėdami uždaryti griovį, tiesiog privažiuokite arčiau krašto.","Gilinkite tranšėją toliau be apsaugos.","Įtrūkimai ir žemės judėjimas gali rodyti nestabilumą ir reikalauti tolesnio saugos įvertinimo."],"b-betanken":["Į ką atkreipiate dėmesį pildami degalus į žemės kasimo mašiną?","Bakas beveik tuščias.","Užfiksuokite variklį ir uždegimo šaltinius pagal gamintojo instrukcijas ir venkite išsiliejimo.","Salone visada papildykite benziną arba dyzeliną.","Rūkyti pilant degalus, kai nėra vėjo.","Gaisro ir aplinkos pavojai dirbant su kuru reikalauja atitinkamų apsaugos priemonių."],"b-laufwerk":["Kodėl vikšrus ir važiuoklę reikia reguliariai tikrinti?","Važiuodami pastebite neįprastą vibraciją.","Kad mašina galėtų judėti greičiau.","Kadangi žala gali turėti įtakos saugiam valdymui ir stabilumui.","Nes dirbti visada leidžiama be vizualinės apžiūros.","Pavaros pažeidimas gali turėti įtakos manevringumui, stabilumui ir saugiam naudojimui."],"b-einweisen":["Ko reikia dirbant šalia viešojo pėsčiųjų eismo?","Ekskavatorius dirba tiesiai ant šaligatvio krašto.","Pėstieji turėtų patys judėti sūpynių zonoje.","Tiesiog užklijuokite ženklą ant kastuvo.","Efektyviai atitverkite pavojingą zoną ir saugiai nukreipkite eismą.","Tretieji asmenys neturi patekti į žemės kasimo mašinų pavojingą zoną; Būtinos tinkamos užtvaros ir eismo maršrutai."],"g2-fahrweg":["Priekyje ant kelio išsiliejo skystis. Kaip jums sekasi?","Šakinis krautuvas važiuotų tiesiai virš slidžios vietos.","Nustokite važiuoti ir užfiksuokite arba pašalinkite pavojingą vietą.","Važiuokite per vietą kuo greičiau, kai šakė pakelta.","Tikėkitės sausesnių padangų ir toliau važiuokite nepakitę.","Užterštos trasos kelia pavojų stabilumui ir turi būti tinkamai apsaugotos prieš važiuojant jais."],"g2-sichtladung":["Aukštas padėklas užstoja vaizdą į priekį. Kas yra teisinga?","Turite važiuoti į saugyklą ir nematote maršruto.","Pakelkite padėklą aukštyn, kol pamatysite po juo.","Važiuokite tik tinkamais ir saugiais būdais, pvz., važiuokite atbuline eiga gerai matomoje vietoje.","Vis tiek galite važiuoti keliu be kelrodžio ar aiškaus vaizdo.","Važiavimo kryptis ir matomumas turi leisti saugiai stebėti eismo maršrutą; Kroviniai neturi pakeisti vizualinio patikrinimo."],"g2-fussgaengerstop":["Prie pat šakinio krautuvo sustoja pėstysis. ka tu darai?","Asmuo yra galimo vairavimo ir sukimosi diapazone.","Aplenk pėsčiąjį trumpam padidindamas greitį.","Važiuokite pro asmenį su pakeltu kroviniu.","Sustokite ir toliau važiuokite tik saugiu atstumu.","Žmonės turi būti atokiau nuo pavojaus zonos; Jei reikia, kelionę reikia nutraukti."],"g2-hubmast":["Ant kėlimo stiebo pastebėjote pažeistą hidraulinę liniją. Kas taikoma?","Iš padargo akivaizdžiai bėga hidraulinė alyva.","Išjunkite šakinį krautuvą ir praneškite apie žalą.","Keldami patikrinkite nuotėkį ranka.","Mažesnius krovinius kelkite tik tol, kol baigsis pamaina.","Hidrauliniai pažeidimai gali sukelti nekontroliuojamus judesius; saugus naudojimas negarantuojamas iki bandymo."],"g2-lagerregal":["Padėklą norite laikyti lentynoje. Ką pirmiausia patikrinsi?","Lentynų lygis yra aukštas ir turi būti išlaikyta apkrova.","Kuo greičiau stumkite padėklą ant lentynos.","Patikrinkite lentynos skyrių, krovinio svorį ir laisvą sandėliavimo vietą.","Apskaičiuokite bendrą svorį tik pagal dėžių skaičių.","Lentynos ir krovinių gabenimo įranga turi atitikti krovinio ir sandėliavimo situaciją."],"g2-batterieschaden":["Šakinio krautuvo akumuliatorius pažeistas išoriškai. Kas yra teisinga?","Prieš pakraunant pastebimi įtrūkimai arba neįprastas skystis.","Pažeidimus uždenkite lipnia juosta ir nedelsdami įdėkite.","Leiskite kitam asmeniui įkrauti akumuliatorių jo nepatikrinęs.","Nekraukite ir nenaudokite ir informuokite atsakingus specialistus.","Pažeisti akumuliatoriai kelia elektros ir cheminių pavojų pavojų, todėl juos reikia profesionaliai įvertinti."],"g2-fahrerkabine":["Kas taikoma palaidiems daiktams vairuotojo zonoje?","Įrankiai yra ant grindų šalia valdymo pedalų.","Pašalinkite daiktus ir laikykite darbo vietą laisvą.","Vairuodami įrankį laikykite tik viena koja.","Paslėpkite laisvas dalis po vairuotojo sėdyne.","Atsilaisvinę daiktai gali užblokuoti pedalus ir pabloginti saugų automobilio valdymą."],"g2-uebergabe":["Pakeitę pamainą, perimate šakinį krautuvą. Kas tai apima?","Paskutinį kartą transporto priemone naudojosi kolega.","Tarkime, kad kolega perėmė visus patikrinimus.","Atlikite reikiamą apžiūrą ir pasiteiraukite apie žinomus defektus.","Pradėkite kelionę nežiūrėdami į mašiną.","Perimantis asmuo prieš naudojimą turi įsitikinti, kad jis yra saugios būklės."],"g2-transportsicherung":["Ant padėklo atsilaisvino aukštas daiktas. Kaip elgiatės?","Stabdant krovinys gali pakrypti į priekį.","Šakę neškite ypač aukštai, kad krovinys išliktų stabilus.","Tiesiog lėtai važiuokite posūkiais, greičiau eikite tiesiai.","Pastatykite krovinį stabiliai ir apsaugokite, kad nenuvirstų ar nenukristų.","Atsipalaidavę kroviniai prieš transportavimą turi būti stabilizuoti, kad stabdant ir važiuojant jie nenukristų."],"g2-arbeitsende":["Kas svarbu, kai krautuvas be priežiūros?","Jūs baigiate pamainą ir paliekate teritoriją.","Saugiai pastatykite automobilį ir apsaugokite jį nuo nuriedėjimo ir neleistino naudojimo.","Palikite raktą, kad kolegos galėtų surasti mašiną.","Šakutę palikite akių lygyje, kad ji būtų matoma.","Saugi stovėjimo aikštelė apima nuleistą krovinio tvarkymą ir apsaugą nuo judėjimo ir neteisėto paleidimo."],"g2-bremsweg":["Kodėl reikia atkreipti ypatingą dėmesį į stabdymo kelią esant apkrovai?","Šakinis krautuvas gabena sunkius krovinius per sandėlio koridorių.","Su dideliu kroviniu visada stabdykite vėliau nei be krovinio.","Sureguliuokite greitį pagal matomumą, žemės ir apkrovos sąlygas.","Stabdydami staigiai pakelkite krovinį, kad lėtėtų geriau.","Masė ir kelio būklė įtakoja stabdymo kelią; pritaikytas greitis yra svarbiausia."],"g2-rampe":["Ką tikrinate prieš lipdami į stačią rampą?","Maršrutas gali būti per status transporto priemonei.","Važiuokite rampa didžiausiu greičiu, nepaisant nuolydžio.","Važiuokite per rampos kraštą su pakeltu kroviniu.","Patikrinkite leistiną nuolydį ir saugų darbo režimą pagal transporto priemonės specifikacijas.","Galima naudoti tik numatytas eksploatacijos ribas; Naudojimo instrukcijos ir apkrovos valdymas yra lemiami."],"g2-zinke":["Padėklas yra platesnis nei šakės atstumas. Į ką reikia atsižvelgti?","Planuojate prisiimti neįprastai didelį krūvį.","Sureguliuokite šakės atstumą ir tvirtinimo taškus, kad jie atitiktų apkrovą.","Jei apkrova per plati, naudokite tik vieną noragą.","Pakelkite krovinį kampu, kol jis pasieks reikiamą padėtį.","Tolygus ir tinkamas apkrovos sugėrimas sumažina slydimą ir apsivertimą."],"g2-betriebsanweisung":["Kokį vaidmenį atlieka operatyvus eismo reguliavimas?","Sandėlyje galioja pažymėtos vienpusės ir pėsčiųjų zonos.","Su šakiniais krautuvais galioja tik viešųjų kelių taisyklės.","Laikykitės nurodytų maršrutų ir eismo taisyklių.","Nepaisykite ženklų, kai transporto priemonė pakrauta.","Įmonės maršrutai ir saugos taisyklės saugo šakinių krautuvų eismą ir pėsčiomis einančius žmones."],"g2-nothalt":["Vairas važiuojant reaguoja neįprastai. Kas yra teisinga?","Transporto priemonės nebegalima valdyti kaip įprasta.","Važiuokite didesniu greičiu, kad vairas būtų jautresnis.","Klaidą kompensuokite ypač dideliais vairo įlinkiais.","Sustokite saugioje vietoje ir patikrinkite automobilį.","Sutrikęs vairavimas kelia pavojų saugiam valdymui; mašina neturi būti toliau naudojama nekontroliuojamai."],"g2-anschlagkette":["Norite krautuvu perkelti laisvai kabantį krovinį. Kas taikoma?","Krovinys turi kabėti ant kablio po šakėmis.","Tik su patvirtintu įrenginiu ir tinkama krovinių nešimo įranga.","Bet kokia grandinė tiks, jei krovinys nėra sunkus.","Užfiksuokite grandinę tiesiai tarp abiejų šakių.","Laisvai kabantys kroviniai keičia stabilumą; Reikalingi gamintojo patvirtinimai ir tinkamos patalpos."],"g2-rollenlast":["Cilindrinė dalis nepritvirtinta ant padėklo. ka tu darai?","Krovinys transportavimo metu gali riedėti.","Prie padėklo priartėkite ypač trūkčiojant.","Prieš paimdami padėklą, užfiksuokite komponentą, kad jis nenuriedėtų.","Padėkite noragus pakankamai aukštai, kad komponento nesimatytų.","Apvalios arba riedančios apkrovos reikalauja patikimos apsaugos nuo padėties pasikeitimo."],"g2-pruefplakette":["Kaip žinoti, ar šakinį krautuvą galima naudoti?","Prie mašinos priklijuotas apžiūros lipdukas.","Bet koks lipdukas visada pakeičia kasdienę vizualinę apžiūrą.","Tarpo trūkumą galima pakeisti atsargiu vairavimu.","Be transporto priemonės patikrinimo, reikia atsižvelgti į galiojančią bandymo būseną ir eksploatavimo patvirtinimą.","Pasikartojantys bandymai ir kasdienė eksploatavimo kontrolė atlieka skirtingas saugos funkcijas."],"g2-licht":["Staiga sandėlyje užgeso apšvietimas. Kas yra teisinga?","Jūs nebegalite saugiai pamatyti kliūčių kelyje.","Nustokite važiuoti, kol bus garantuotas saugus matomumas.","Padidinkite važiavimo greitį, kad išvažiuotumėte iš tamsios zonos.","Toliau važiuokite pakeltomis šakėmis be vizualinio patikrinimo.","Maršrutu, kurio negalima saugiai nepastebėti, negalima važiuoti be veiksmingų saugos priemonių."],"g2-ueberhang":["Krovinys tęsiasi toli už šakės šono. Ką tu tikrini?","Padėklą norite gabenti pro siaurus vartus.","Šoninę projekciją kompensuokite greita kreive.","Prieš važiuodami įvertinkite prošvaisą, stabilumą ir leistiną keliamąją galią.","Važiuokite krovinį didžiausiu greičiu, nepaisant jo formos.","Iškyšos padidina susidūrimo riziką ir gali pakeisti stabilumą bei reikalingą eismo erdvę."],"g2-wartungsbereich":["Priešais techninės priežiūros zoną yra užtvaros. kaip tu elgiesi?","Jūsų įprastas maršrutas laikinai uždarytas.","Trumpam perkelkite kliūtis ir pravažiuokite nepastebimai.","Važiuokite tiesiai per darbo zoną esant apkrovai.","Stebėkite uždarymą ir pasirinkite patvirtintą alternatyvų maršrutą.","Be leidimo negalima patekti į aptvertas zonas ar važiuoti per jas."],"g2-bremsprobe":["Kada prasminga atlikti darbinio stabdžio veikimo patikrinimą?","Prieš darbą paruošiate krautuvą.","Kaip būtino patikrinimo prieš naudojimą dalis.","Atlikti tik po rimtos avarijos.","Tik jei sunkvežimis jau pasiekė didelį greitį.","Prieš naudojant patikrinamas saugai svarbių įrenginių funkcionalumas."],"g2-fahrzeuganhaenger":["Norite traukti priekabą su šakiniu krautuvu. Ko reikia?","Įmonė planuoja transportą su prikabintu kroviniu.","Netikrindami pririškite kiekvieną priekabą prie šakės.","Laikykitės gamintojo patvirtinimo, tinkamos jungties ir leistinos tempimo apkrovos.","Tiesiog padidinkite padangų slėgį ir važiuokite.","Traukinį galima saugiai važiuoti tik laikantis techninių specifikacijų ir esant tinkamam susisiekimui."],"g2-rueckfahrt":["Kas svarbu važiuojant atbuline eiga su šakiniu krautuvu?","Sandėlio koridoriuje yra paini zona.","Visada žiūrėkite tik į galinio vaizdo veidrodėlį, nepaisant aplinkos.","Važiuokite be matomumo tol, kol garsinis signalas buvo nuspaustas vieną kartą.","Saugiai stebėkite maršrutą ir žmonių zoną ir, jei reikia, juos instruktuokite.","Važiuojant atbuline eiga reikalingas aiškus vaizdas arba veiksmingos papildomos saugos priemonės."],"g2-lastentnahme":["Iš aukštos lentynos išimate padėklą. Kas yra teisinga?","Paletė gali būti necentruota.","Saugiai paimkite krovinį ir stabilizuokite jį prieš nuleisdami.","Ištraukdami padėklą leiskite pakrypti į šoną.","Patikrinkite po pakeltu padėklu, ar jis nepažeistas.","Kontroliuojamas kėlimas ir nuleidimas apsaugo nuo krovinių kritimo ir pavojingų judesių."],"h2-absenkweg":["Kodėl plotas po kėlimo platforma turi likti laisvas?","Krepšelis nuleidžiamas, o po juo dedamos medžiagos.","Paspauskite medžiagas žemyn su krepšeliu.","Stebėkite tik operatoriaus pėdų sritį.","Nuleidžiant venkite suspaudimo ir susidūrimo pavojaus.","Nuleidimo zonoje neturi būti žmonių ar kliūčių, kurios galėtų įstrigti."],"h2-transporthoehe":["Kaip perkelti mobilią sceną per žemą praėjimą?","Prošvaisa yra mažesnė nei ištiestos strėlės.","Pastatykite platformą į tinkamą transportavimo padėtį pagal naudojimo instrukciją.","Palikite strėlę ištiestą ir judėkite po lubomis.","Prispauskite krepšį prie durų rėmo šono.","Važiuojant, bendras aukštis ir transportavimo padėtis turi atitikti gamintojo specifikacijas ir praėjimą."],"h2-bodenoeffnung":["Šalia scenos grindyse yra neužtikrinta anga. kaip tu reaguoji?","Netoli angos yra vairavimo arba palaikymo taškas.","Padėkite atramą tiesiai ant angos krašto.","Pakeiskite montavimo vietą arba profesionaliai patikrinkite keliamąją galią ir tvirtinimą.","Pavojaus vietą uždenkite tik kartonine dėže.","Angos ir kraštinės gali sugesti veikiant atraminėms apkrovoms, todėl į jas reikia tinkamai atsižvelgti."],"h2-rettungsperson":["Kodėl antrasis asmuo turi būti susipažinęs su gelbėjimo procedūra?","Viršuje operatorius gali tapti nedarbingas.","Taigi darbas krepšelyje paprastai gali vykti be saugumo.","Kad sceną būtų galima eksploatuoti greičiau nei leistina.","Kad kritiniu atveju būtų galima pradėti saugų gelbėjimą.","Gelbėjimo koncepcijoje turi būti atsižvelgta į antžeminę pagalbą gedimo ar avarijos atveju."],"h2-werkzeugabwurf":["Kas taikoma įrankiams dideliame aukštyje?","Atsipalaidavęs įrankis gali nukristi per krepšio kraštą.","Įrankius pritvirtinkite taip, kad jie niekam nekeltų pavojaus ir nenukristų.","Tiesiog uždėkite įrankius ant turėklų, kad sumažintumėte apkrovą.","Jei reikia, išmeskite įrankius iš krepšio.","Krintantys daiktai kelia pavojų žemiau esantiems žmonėms; Medžiaga turi būti saugiai saugoma."],"h2-trittstufe":["Dėžė turėtų tarnauti kaip papildoma vieta stovėti krepšyje. Kas yra teisinga?","Priešingu atveju jūs tik vos pasieksite darbo vietą.","Padėkite dėžutę ant turėklų ir lipkite ant jos.","Nelipkite ant improvizuotų aukštumų; Naudokite tinkamą darbo įrangą.","Sąmoningai įkelkite krepšį virš leistino aukščio.","Improvizuoti pakėlimai kenkia numatytai apsaugai nuo kritimo ir yra neleidžiami."],"h2-lastverteilen":["Į ką atkreipiate dėmesį, kai darbo krepšelyje yra keli žmonės?","Krepšelyje su sunkiais įrankiais dirba du žmonės.","Apkrovą vertinkite tik pagal įrankio dydį.","Sunkius įrankius laikykite tiesiai ant apsauginių turėklų.","Neviršykite leistinos krepšio apkrovos, įskaitant žmones ir įrankius.","Į leistiną apkrovą įeina visi krepšelyje esantys žmonės, medžiagos ir įrankiai."],"h2-abstuetzplatte":["Kada svarstomos papildomos atramų tarpinės?","Montuojamos grindys gali atlaikyti tik ribotą apkrovą.","Jei tai būtina saugiam apkrovos paskirstymui pagal specifikacijas.","Kad atramos būtų kuo arčiau statybinės duobės krašto.","Norint naudoti ilgesnį diapazoną be gamintojo informacijos.","Saugioms atramos jėgoms reikia pakankamai kontaktinių zonų."],"h2-baugrube":["Scena turi būti tiesiai prie statybinės duobės krašto. Ką tu tikrini?","Dėl iškasos duobės podirvis galėjo pasiduoti iš šono.","Ištraukite atramas į kasimo duobę.","Užtikrinkite pakankamą saugų atstumą ir požeminio paviršiaus laikomąją galią.","Riziką kompensuokite tik lėtai keldami krepšį.","Kasimo duobės gali turėti įtakos stabilumui dėl šlaito ir podirvio gedimo."],"h2-witterung":["Naudojimo metu susidaro apledėjimas. Kaip elgiatės?","Valdymo paviršiai ir darbo sritis tampa lygūs.","Pakelkite sceną, kad išvengtumėte sniego ir ledo.","Nekreipkite dėmesio į įspėjimus, kol platforma šviečia.","Nutraukite darbą ir iš naujo įvertinkite darbo sąlygas pagal naudojimo instrukciją.","Pasikeitus orams, gali pasikeisti atsakomybė, veikimas ir saugios naudojimo ribos."],"h2-aufbaukontakt":["Plieninė konstrukcija riboja krepšelio kelią. Kas svarbu?","Keliant kyla pavojus prispausti tarp krepšio ir laikiklio.","Suplanuokite judesius taip, kad jūsų kūnas ir krepšys nebūtų įstrigę.","Paspartinkite kelionę, kad krepšelis greičiau praeitų.","Pastumkite konstrukciją su krepšeliu į šoną.","Suspaudimo taškus tarp platformos ir aplinkos reikia atidžiai stebėti ir kontroliuoti judėjimą."],"h2-sicherheitsabstand":["Kada pavojinga scenos zona turi būti aptverta?","Po sklypu eina viešojo transporto maršrutas.","Tik jei objektas jau nukrito.","Jei judėjimas ar krintantys daiktai gali kelti pavojų tretiesiems asmenims.","Niekada, nes darbinis krepšys iš esmės apsaugo nuo visų pavojų.","Teritorija po scena ir šalia jos turi būti apsaugota nuo numatomų pavojų."],"h2-korbtor":["Kas taikoma darbo krepšelio įėjimo durims?","Jūs jau esate darbiniame aukštyje.","Palikite duris atidarytas, kad galėtumėte greičiau išeiti.","Pririškite duris visam laikui atidarytas virve.","Laikykite duris uždarytas pagal pateiktą užrakinimo mechanizmą.","Pateiktos spynos yra apsaugos nuo kritimo iš darbo krepšio dalis."],"h2-energieleitung":["Kas taikoma, jei oro linija nėra saugiai išjungta?","Dirbate su kėlimo platforma šalia jų.","Užtikrinkite nurodytus saugius atstumus ir būtinas apsaugos priemones.","Perkelkite krepšelį tiesiai prieš liniją, kol jo neliečiate.","Pasitikėkite plastikinėmis padangomis ir dirbkite be jokių spragų.","Elektriniai blyksniai galimi ir be tiesioginio kontakto; Reikalingi saugūs atstumai."],"h2-schwanken":["Darbinis krepšys pradeda neįprastai stipriai siūbuoti. Kas yra teisinga?","Judėjimas nebekontroliuojamas.","Nekontroliuojamai sureguliuokite greitais priešingais judesiais.","Sustabdykite judėjimą ir patikrinkite priežastį arba veikimo sąlygas.","Pridėkite papildomų žmonių į krepšelį, kad jis būtų sunkesnis.","Neįprasta vibracija gali rodyti netinkamas eksploatavimo sąlygas arba gedimą."],"h2-ladegeraet":["Pažeistas elektra valdomos pakopos įkrovimo laidas. ka tu darai?","Jungiant matosi pažeista izoliacija.","Pažeidimą palieskite drėgnomis pirštinėmis.","Kiek įmanoma stipriau įspauskite kištuką į lizdą.","Nepradėkite įkrovimo proceso ir pasirūpinkite, kad kabelis būtų profesionaliai patikrintas.","Pažeisti elektros laidai kelia elektros smūgio ir gaisro pavojų."],"h2-gelaenderanbau":["Ar galite patys nuimti turėklus, kad priartėtumėte?","Komponentas neleidžia žmonėms priartėti prie darbo vietos.","Nekeiskite ir nenuimkite apsauginių įtaisų patys.","Pakėlus turėklus atsukite ir sumontuokite vėliau.","Tęskite darbą be turėklų, kol kas nors stovi šalia.","Konstrukciniai apsauginiai įtaisai negali būti keičiami be leistinų specifikacijų ir saugių pakeitimo priemonių."],"h2-lastkran":["Ar platforma gali būti naudojama kaip kranas kroviniui kelti?","Medžiaga turi būti vežama laisvai pakabinta šalia darbo krepšio.","Kai svoris yra mažesnis už jūsų kūno svorį.","Tik tuo atveju, jei gamintojas ir įranga aiškiai leidžia šį specialų naudojimą.","Tiesiog pritvirtinkite kabliuką prie turėklų ir pakelkite medžiagą.","Kėlimo darbo platformos nėra automatiškai skirtos darbams kranu ar papildomiems pakabinamiems kroviniams."],"h2-arbeitsvorbereitung":["Kas vyksta ruošiantis naujai vietai?","Jūs dar nežinote statybvietės.","Tiesiog įvertinkite atstumą iki artimiausios automobilių stovėjimo aikštelės.","Nepriklausomai nuo aplinkos, nedelsdami ją visiškai išplėskite.","Įvertinkite pavojus, dirvožemį, eismo kelius, gelbėjimo ir įrangos tinkamumą.","Su vieta susijusi rizikos įvertinimas yra būtina saugių eksploatavimo sąlygų sąlyga."],"h2-kabelschlaufe":["Scenos kelyje yra maitinimo laidas. Kas yra teisinga?","Judėjimo metu kabelis gali įstrigti.","Išvalykite kelią ir apsaugokite elektros laidus nuo pažeidimų.","Kabelį su ratais naudokite kaip kelio slenkstį.","Pakelkite krepšį netikrindami grindų ploto.","Perbraukti arba suspausti kabeliai gali sukelti elektros ir mechaninių pavojų."],"h2-leitungsnaehe":["Kas paaiškina elektros sistemos apsaugos priemones?","Platforma turėtų veikti arti veikiančios įrangos.","Žmogus krepšelyje sprendžia tik iš akies.","Įtraukti atsakingas institucijas ir įgyvendinti suderintas apsaugos priemones.","Atstumas bus nustatytas tik prasidėjus darbui.","Darbas šalia elektros sistemų reikalauja planuotų ir suderintų apsaugos priemonių."],"h2-funkkommunikation":["Kodėl signalai tarp grindų ir krepšio turi būti aiškūs?","Žemėje esantis žmogus padeda manevruoti.","Kad keli žmonės vienu metu galėtų duoti prieštaringus nurodymus.","Kad būtų galima išbandyti avarinį nuleidimą be instrukcijų.","Taigi, kad judesiai būtų atliekami tik po aiškaus bendravimo.","Aiškus bendravimas sumažina neteisingus judesius ir susidūrimus manevruojant."],"h2-neuebedienung":["Perjungiate į kitokio tipo etapą. Ko reikia?","Veikimo funkcijos labai skiriasi.","Prietaiso instrukcija prieš savarankišką naudojimą.","Tiesiog perskaičiau įmonės logotipą ant įrenginio.","Bandomasis važiavimas su jau prailgintu krepšiu be instrukcijų.","Vien tik kvalifikacija nepakeičia mokymo konkretaus tipo įrenginiuose."],"h2-steckanschluss":["Ką reikia patikrinti prieš prijungiant įkroviklį?","Elektrinę darbo platformą reikia įkrauti.","Naudokite bet kokį lizdą, neatsižvelgiant į būklę ir saugiklį.","Patikrinkite tinkamą jungtį ir nepažeistą laidą pagal gamintojo instrukcijas.","Įkrovimo metu reguliariai ištraukite maitinimo kištuką.","Tinkamos ir nepažeistos elektros jungtys apsaugo nuo elektros smūgio ir gaisro."],"h2-absperrpersonal":["Kėlimo darbų metu žmogus patenka į aptvertą zoną. ka tu darai?","Asmenį galite matyti tiesiai po darbo krepšeliu.","Jei asmuo dėvi apsauginį šalmą, važiuokite toliau.","Numeskite įrankį jų kryptimi kaip įspėjamąjį signalą.","Sustabdykite pavojingą judėjimą ir išvalykite vietą.","Užtvaras nepakeičia pavojaus zonos stebėjimo eksploatacijos metu."],"k2-arbeitsplanung":["Ką reikėtų įtraukti į pasirengimą darbui prieš krano operaciją?","Pakrovimas, vieta ir transportavimo maršrutas dar nesuderinti.","Pirmiausia pakelkite sunkiausią krovinį, nieko neplanuodami.","Pažymėkite tik trumpiausią maršrutą ant salės grindų.","Iš anksto išsiaiškinkite keliamąją galią, stropus, krovinio kelią ir pavojingą zoną.","Planuojamas krano judėjimas reikalauja tinkamo krovinio valdymo, saugių maršrutų ir suderintų apsaugos priemonių."],"k2-hakenposition":["Kaip krano kablys yra ant krovinio prieš pakėlimą?","Tvirtinimo taškai yra žemiau krano.","Kiek įmanoma vertikaliai virš svorio centro pagal stotelę.","Pasukite toli į šoną, kad krovinys svyruotų greičiau.","Bet kokiu atveju prie išorinio krovinio krašto, nepriklausomai nuo svorio centro.","Vertikalus jėgos panaudojimas ir tinkami tvirtinimo taškai sumažina judėjimą į šoną ir nekontroliuojamus judesius."],"k2-hakengabel":["Apkrovos kablys rodo pastebimą deformaciją. Kas taikoma?","Kablys atrodo išlenktas iš įprastos būsenos.","Su kita apkrova sulenkite deformaciją atgal.","Sustabdykite krano veikimą ir paprašykite specialisto patikrinti kabliuką.","Pritvirtinkite tik lengvus krovinius ir tęskite darbą.","Deformacija gali turėti įtakos kablio saugumui; neleistinas tolesnis naudojimas."],"k2-zugueberlast":["Našta yra sunkesnė, nei manyta iš pradžių. ka tu darai?","Pasiruošimo metu atsiranda nauja informacija apie svorį.","Pakeiskite saugos rezervą greitesniu kėlimu.","Nepaisykite krovinio svorio, pritvirtindami jį prie kito taško.","Nustatykite faktinę apkrovą ir dar kartą patikrinkite apkrovos ribas.","Saugus kėlimas reikalauja patikimų krovinio duomenų ir visų atitinkamų apkrovos pajėgumų laikymosi."],"k2-arbeitskorb":["Ar paprastas krano kabliukas gali lengvai nešti žmones?","Žmogus nori patekti į aukštą darbo vietą.","Ne, keleivių vežimui reikia leistinų specialių įrenginių ir priemonių.","Taip, jei žmogus laikosi už virvės stropo.","Taip, kai tik insultas atliekamas ypač lėtai.","Vežti žmones leidžiama tik esant specialioms šiam tikslui numatytoms sąlygoms."],"k2-bruecke":["Tiltinis kranas juda bendru salės taku. Kas svarbu?","Darbuotojai lieka transporto keliu.","Važiuokite su kroviniu tiesiai virš darbuotojų galvų.","Efektyviai pasirūpinkite, kad krovinio maršrutas ir eismo zona būtų aiškūs ir saugūs.","Naudokite tik įspėjamąjį signalą, o ne kitas priemones.","Žmonės, kuriems gresia pavojus, neturi būti po pakabintais kroviniais arba jų transportavimo kelyje."],"k2-zweitekrane":["Du kranai dirba persidengiančioje srityje. Ko reikia?","Strėlės arba kroviniai gali susidurti.","Abu kranininkai dirba vienu metu be išankstinio susitarimo.","Judėjimas sąmoningai pagreitinamas, kad būtų išvengta sankryžų.","Koordinuoti operacijas ir imtis atitinkamų priemonių, kad būtų išvengta abipusių grėsmių.","Sutampančios darbo sritys reikalauja koordinuoto veiklos organizavimo ir tinkamų apsaugos priemonių."],"k2-pruefbuch":["Kokia yra privalomos kartotinės krano patikros reikšmė?","Mašina reguliariai naudojama eksploatacijose.","Jis operatyvinę kontrolę papildo nustatyta ekspertize.","Jis visam laikui pakeičia bet kokį vizualinį patikrinimą prieš pradedant darbą.","Tai reikalinga tik po avarijos.","Pasikartojančių patikrinimų ir nuolatinės veiklos kontrolės uždaviniai yra skirtingi."],"k2-absetzflaeche":["Numatytas išdėstymo plotas yra nelygus. Kaip elgiatės?","Padėtas krovinys gali apvirsti.","Padėkite krovinį ant vieno kampo ir leiskite jam kabėti nepakitusią.","Paruoškite tinkamus, laikančius ir stabilius pagrindus arba paviršius.","Nuleiskite vieną žmogų po kroviniu.","Padėjimo vietos turi saugiai atlaikyti krovinį ir užkirsti kelią pavojingam apvirtimui ar riedėjimui."],"k2-anfahrbereich":["Prieš kranui pradedant judėti, kelionės zonoje yra vienas žmogus. ka tu darai?","Maršrutą užblokavo žmogus.","Trumpu bandomuoju važiavimu nustumkite asmenį į šalį.","Išjunkite naudodami tik ribinį jungiklį be vizualinio patikrinimo.","Pradėkite judėti tik tada, kai pavojaus zona yra laisva ir saugi.","Važiuojant ir pasukami judesiai neturi kelti pavojaus žmonėms."],"k2-schlaffseil":["Kodėl nuleidus kėlimo lyną neturėtų nevaldomai atsilaisvinti?","Krovinys uždėtas, kabliukas nuleistas toliau.","Kad lynas ir kabliukai neįstrigtų arba nebūtų nekontroliuojamai apkrauti.","Kad po to krovinį būtų galima tempti į šoną lynu.","Kad stropai atsikabintų nuo kabliuko.","Nekontroliuojamas kabelių tiesimas gali sukelti susipainiojimą ir pavojingą krovinio judėjimą."],"k2-pendel":["Vežamas krovinys pradeda siūbuoti. Kas yra teisinga?","Krovinys juda į šoną daugiau nei planuota.","Kompensuokite greitais priešpriešiniais judesiais ir visu greičiu.","Kontroliuojamai sumažinkite judesius ir nuraminkite kelionę į darbą ir atgal, kai pavojingoje zonoje nėra žmonių.","Laikykite siūbuojamą krovinį plikomis rankomis.","Svyruojančios apkrovos gali paveikti žmones ir įrenginius; ramūs judesiai sumažina riziką."],"k2-funkakku":["Krano radijo valdymas turi silpną akumuliatorių. Kas taikoma?","Kėlimo metu jungtis gali nutrūkti.","Greitai pakelkite krovinį, kol valdiklis nesuges.","Jei ryšys nutrūksta, perkelkite krovinį traukdami už diržo.","Prieš naudodami įsitikinkite, kad valdymo jungtis yra patikima.","Patikimas valdymas ir ryšys yra būtinos kontroliuojamo krano judėjimo sąlygos."],"k2-mehrereanschlaeger":["Du žmonės vienu metu duoda skirtingus signalus krano operatoriui. Kas yra teisinga?","Ženklai prieštarauja vienas kitam.","Nutraukite judėjimą ir išaiškinkite aiškią atsakomybę.","Pirmenybę teikite toliau esančio asmens ženklui.","Tęskite judesį pagal savo jausmus.","Kranų vairuotojams reikalingas aiškus ir nedviprasmiškas bendravimas, ypač kai krovinių keliai yra painūs."],"k2-endabschaltung":["Kodėl ribinis jungiklis neturėtų būti netinkamai naudojamas kaip įprastas eigos apribojimas?","Krovinys dažnai perkeliamas iki didžiausio kėlimo atstumo.","Ribiniai jungikliai paprastai leidžia greičiau kelti be matomumo.","Galiniai jungikliai yra saugos įtaisai ir nepakeičia kontroliuojamo veikimo.","Su kiekvienu smūgiu jie turi būti kuo stipresni.","Apsaugos įtaisai yra skirti apsaugoti nuo pavojų ir neturi būti naudojami per daug, kaip planuota."],"k2-wetterbeobachtung":["Esant didelės teritorijos apkrovai, vėjas žymiai sustiprėja. Ko reikia?","Didelis komponentų plotas veikia kaip burė.","Visada pakelkite krovinį aukščiau, kad vėjas veiktų mažiau.","Stropus pakeiskite plonesniais.","Įvertinkite vėjo ir veikimo ribas ir, jei reikia, pakoreguokite kėlimą.","Vėjas gali sukelti didelių papildomų jėgų ir švytuoklės judesių, ypač esant didelėms apkrovoms."],"k2-ortswechsel":["Kas svarbu perkeliant mobilųjį kraną į naują vietą?","Keičiasi podirvio ir atramos sąlygos.","Prieš vėl paimdami krovinį, patikrinkite stovo vietą ir atramą.","Netikrindami pritaikykite ankstesnės vietos nustatymus.","Kėlimo metu vėl sureguliuokite atramą.","Kiekvienoje montavimo vietoje gali būti skirtingos žemės ir atramos apkrovos sąlygos."],"k2-betriebsbereich":["Manoma, kad kranas turi dirbti kitoje gatvės pusėje. Ką reikia išsiaiškinti?","Trečiosios šalys gali patekti į pavojingą zoną.","Užfiksuokite kelią tik įspėjamuoju signalu.","Reikalingi blokavimai, balsavimas ir apsaugos priemonės priešais centrą.","Pakelkite krovinį ant transporto priemonių kuo greičiau jo neužfiksuodami.","Saugus eismo maršrutas apsaugo nuo nereikalingos rizikos trečiosioms šalims dėl krovinių ir krano judėjimo."],"k2-hochheben":["Po bandomojo kėlimo krovinys kabo aiškiai kreivai. Kas yra teisinga?","Akivaizdu, kad dėmesys buvo neteisingai įvertintas.","Tęskite kėlimą, kad disbalansas išsitaisytų savaime.","Tegul vienas asmuo traukia pasvirusią apkrovą.","Saugiai nuleiskite krovinį ir dar kartą patikrinkite tvirtinimą bei svorio centrą.","Bandomasis keltuvas naudojamas neteisingam tvirtinimui ir nestabiliai krovinio padėčiai nustatyti prieš transportavimą."],"k2-schwebelast":["Ar galite palikti pakeltą krovinį kabantį be priežiūros?","Pamaina baigiasi, bet krovinys vis dar ant kablio.","Ne, saugiai nuleiskite krovinį ir tinkamai pritvirtinkite kraną.","Taip, jei kranas užrakintas, kad nepajudėtų.","Taip, kol ant žemės yra įspėjamasis ženklas.","Iš esmės pakabinami kroviniai neturėtų būti palikti be priežiūros."],"k2-mitnahme":["Kolegė nori važiuoti krano kroviniu. Kas taikoma?","Krovinys turi būti gabenamas į aukštesnį tašką.","Jodinėti leidžiama, jei kolega dėvi šalmą.","Žmonių negalima vežti ant įprastų krovinių arba pritvirtinti prie jų.","Važiuoti visada leidžiama, kol krano vairuotojas pažįsta kolegą.","Vežant žmones kartu su kroviniais kyla didelė rizika nukristi ir sutraiškyti."],"k2-warnsignal":["Krano veikianti įspėjimo sistema sugenda. Kas yra teisinga?","Įspėti prieš išvažiuojant nebegalima.","Nepaisykite sistemos, kai variklis veikia.","Visam laikui pakeiskite įspėjimą bakstelėdami korpusą.","Praneškite apie su sauga susijusį gedimą ir nutraukite veiklą pagal instrukcijas.","Reikalingi įspėjimo įtaisai turi veikti, kad žmonės būtų laiku apsaugoti."],"k2-schneekante":["Ant užšalusios nelygios žemės reikia palaikyti mobilųjį kraną. Kas taikoma?","Dirvožemis atšildamas gali prarasti laikomąją galią.","Įvertinkite apkrovą ir atramos situaciją tikromis sąlygomis.","Užšalusi žemė visada turi bet kokią laikomąją galią.","Atramas dėkite tik ant mažų akmenėlių.","Temperatūra, drėgmė ir podirvio struktūra įtakoja kranų vietų laikomąją galią."],"k2-laufkatze":["Vežimėlis juda link kliūties. Kaip elgiatės?","Vairavimo zonoje yra objektas.","Lėtai stumkite daiktą su kroviniu.","Sustabdykite judėjimą laiku ir saugiai pašalinkite kliūtį.","Važiuokite pro kliūtį padidintu greičiu.","Krano judesiai turi būti nukreipti taip, kad nesusidurtų su kliūtimis."],"k2-anschlagaufnahme":["Krovinį turėtumėte paimti naudodami neskirtą kilpą. Kas yra teisinga?","Akutė galėjo būti skirta tik dangčiui montuoti.","Kiekviena kilpa tinka pilnai krano apkrovai.","Į kilpą vienu metu užkraukite tik du žmonės.","Prieš naudodami patikrinkite tvirtinimo taško apkrovą ir tinkamumą.","Ne kiekviena esama kilpa yra stabilus krano krovinių tvirtinimo taškas."],"l2-seilbruch":["Vielinis lynas rodo keletą nutrūkusių atskirų laidų. Kas yra teisinga?","Lūžio taškai yra laikančiosios virvės srityje.","Nenaudokite kėlimo įrangos ir leiskite ją profesionaliai įvertinti.","Plikomis rankomis sulenkite vielos galus atgal.","Jei apkrova ypač lengva, naudokite virvę.","Vielos pertraukos gali būti atmetimo kriterijus; Pažeisti lynai turi būti profesionaliai įvertinti."],"l2-schaekel":["Kas yra labai svarbu naudojant pančius?","Stropą ir krovinį jungia pančiai.","Pakeiskite varžtą bet kokia vinimi.","Patikrinkite tinkamą apkrovą, nepažeistą būklę ir tinkamus varžtus.","Įvertinkite apkrovą pagal spalvą.","Pančiai turi būti tinkamo dydžio, naudojami visiškai ir numatyta krovimo kryptimi."],"l2-tragfaehigkeit":["Į ką reikia atsižvelgti naudojant kelias sruogas?","Sruogos eina kampu vertikaliai.","Tiesiog pridėkite kiekvienos sruogos apkrovą pagal pageidavimą.","Pakabinkite krovinį tik ant lengviausios sruogos.","Atsižvelkite į viso tipo inkaro ir kampo laikomąją galią.","Pasvirimo kampas ir efektyvus sruogų skaičius labai įtakoja leistiną apkrovą."],"l2-schweissnaht":["Ar improvizuotą tvirtinimo tašką galima privirinti prie apkrovos?","Tinkamų krovinio paėmimo taškų nėra.","Naudokite tik tinkamai suprojektuotus ir patvirtintus tvirtinimo taškus.","Bet kokios suvirinimo siūlės pakanka be bandymo.","Įkiškite kabliuką per lakštinio metalo angą.","Turi būti įrodyta, kad tvirtinimo taškai yra tinkami kėlimo jėgoms."],"l2-einseitig":["Vienoje pusėje krovinys yra žymiai sunkesnis. Kaip jums sekasi?","Svorio centras yra už geometrinio centro ribų.","Palikite visas sruogas tokio pat ilgio, nepriklausomai nuo svorio centro.","Nustatykite svorio centrą ir atitinkamai sureguliuokite padėtį.","Pirmiausia pakelkite krovinį iki viso kėlimo aukščio.","Jei svorio centras yra ne centre, apkrovos gali netikėtai nukrypti arba gali būti perkrautos atskiros gijos."],"l2-kettenriss":["Kas taikoma grandininiam stropui su matomais įtrūkimais?","Vienoje iš grandinės grandžių yra įtrūkimas.","Pažymėkite plyšį dažais ir pakelkite nepakitusią.","Apvyniokite nuorodą viela ir naudokite dar kartą.","Nedelsdami nuimkite grandinę ir informuokite atsakingą asmenį.","Įtrūkimai laikančiosiose grandinės grandyse yra su sauga susijusi žala, todėl jų eksploatavimą reikia nutraukti."],"l2-lastfuehrung":["Kaip nešti didelį krovinį, kai yra sukimosi pavojus?","Krovinys kėlimo metu gali svyruoti į šoną.","Naudokite tinkamus nukreipimo įtaisus ir saugų atstumą.","Važiuodami laikykite krovinį tiesiai tarp rankų.","Ženkite po apkrova ir išlygiuokite ją iš apačios.","Krovinio nukreipimas neturi sukelti rankų ar kūnų patekimo į pavojingą zoną."],"l2-schnueren":["Kas svarbu tvirtinant raištelius?","Stropas yra nukreipiamas aplink komponentą.","Tarkime, kad apkrova yra tokia pati kaip ir bet kurio kito tipo inkaras.","Atsižvelkite į tvirtinimo tipo tinkamumą ir leistiną apkrovą pagal ženklinimą.","Netikrindami bet kokiu mastu sutraukite stropų pavarą.","Suvarstymo tvirtinimo tipas gali pakeisti leistiną apkrovą ir turi būti naudojamas teisingai."],"l2-winkelmesser":["Kodėl negalite nekreipti dėmesio į plokščią sruogų kampą?","Dvi stropų linijos eina beveik horizontaliai iki krovinio.","Plokščias kampas automatiškai sustiprina sruogą.","Apkrova visada paskirstoma vienodai, nepriklausomai nuo kampo.","Didelės gijų jėgos gali viršyti leistiną apkrovą.","Didėjant kampui į vertikalę, didėja sruogų įtempimai."],"l2-heisse-last":["Ką reikia patikrinti, ar apkrova karšta?","Plieninė dalis neseniai buvo termiškai apdorota.","Laikykitės stropų temperatūros ribų ir tinkamo pasirinkimo.","Kiekvienas tekstilinis diržas gali atlaikyti bet kokią temperatūrą.","Kai karšta, ženklinimas nesvarbus.","Temperatūra gali paveikti leistiną stropų keliamąją galią."],"l2-abstand":["Ar galite pakišti pirštus po kroviniu jį nuleidžiant?","Krovinys turi nusileisti ant paviršiaus milimetro tikslumu.","Taip, jei mūvite darbo pirštines.","Ne, laikykitės atstumo ir naudokite tinkamas priemones.","Taip, jei krano judėjimas yra ypač lėtas.","Kūno dalys tarp krovinio ir pagrindo gali įstrigti."],"l2-verbindung":["Stropo grandinės jungiamoji grandis neužrakinta. Kas taikoma?","Trūksta tvirtinimo detalės.","Naudokite užraktą be užrakto, kai niekas nemato.","Užklijuokite elementą lipnia juosta.","Nemuškite, kol tvirtinimo detalė nėra tinkamai pritvirtinta.","Jungiamieji elementai turi būti visiškai pritvirtinti pagal jų konstrukciją."],"l2-lasthaken":["Ką tikrinate kabindami ant krano kablio?","Į kabliuką reikia įvesti keletą stropų.","Užtikrinkite patikimą kabliukų ir pakabos tvirtinimą ir tinkamumą.","Uždėkite stropus ant kabliuko galo.","Pakeiskite kablio užraktą kabelio raiščiu.","Jėga turi būti taikoma taip, kaip numatyta, nurodytose vietose."],"l2-fasern":["Kėlimo diržas rodo stiprų šiurkštumą ir pluošto pažeidimus. Kas yra teisinga?","Atraminiai pluoštai yra akivaizdžiai pažeisti.","Uždenkite žalą kitu mazgu.","Atskirkite kėlimo diržą ir leiskite jį patikrinti specialistui.","Tada greičiau kelkite krovinį.","Pažeisti laikantys pluoštai gali žymiai sumažinti kėlimo diržo keliamąją galią."],"l2-anheben":["Kas taikoma iš karto po pirmojo kėlimo centimetro?","Krovinys tik pakyla nuo pagrindo.","Nevaldydami patraukite krovinį į visą aukštį.","Po kroviniu patikrinkite, ar stropai yra įtempti.","Patikrinkite sustojimo padėtį, pusiausvyrą ir judėjimo elgesį.","Kontroliuojamas bandomasis pakėlimas leidžia matyti galimą nestabilumą prieš tolesnį transportavimą."],"l2-lastgewichte":["Krovinio svoris nežinomas. Kas yra teisinga?","Komponentas neturi svorio žymėjimo.","Prieš rinkdamiesi stropus, nustatykite apkrovos svorį.","Apskaičiuokite svorį pagal krovinio spalvą.","Naudokite bet kokį dvigubo ilgio diržą.","Neturint žinomo ar patikimai nustatyto svorio, stropų tinkamumas negali būti užtikrintai patikrintas."],"l2-lose-teile":["Ant pakeliamo krovinio yra palaidi įrankiai. ka tu darai?","Keliant įrankiai gali nukristi.","Vairuodami įrankius laikykite viena ranka.","Prieš keldami nuimkite arba veiksmingai pritvirtinkite palaidus daiktus.","Truputį greičiau pakelkite krovinį, kad niekas neslystų.","Atsipalaidavę daiktai gali nukristi ir sukelti pavojų rajone esantiems žmonėms."],"l2-wind":["Pučiant stipriam vėjui pritvirtinamas didelis krovinys. Kas taikoma?","Komponentas suteikia vėjui didelį atakuojamo paviršiaus plotą.","Pakelkite krovinį neatsižvelgdami į siūbuojančius judesius.","Papildomi žmonės turėtų laikyti krovinį tiesiai.","Įvertinkite vėjo sąlygas ir nekelkite, jei situacija nesaugi.","Vėjo jėgos gali paveikti krovinio valdymą ir stabilumą transportavimo metu."],"l2-unterlage":["Kodėl nujunkant krūtimi svarbūs tinkami dokumentai?","Apvalus krovinys nuriedėtų ant žemės.","Tvirtai padėkite krovinį žemyn ir, jei reikia, apsaugokite nuo nuriedėjimo.","Palikite krovinį stovėti tiesiai ant stropų.","Dokumentus po kroviniu stumkite tik juos padėję.","Tinkamos atramos apsaugo nuo apvirtimo ir nepageidaujamų judesių atsisėdus."],"l2-transportweg":["Ką reikia derinti prieš vežant krovinį?","Krovinys perkeliamas per kelias darbo sritis.","Tik numatoma stebulės trukmė.","Saugus apkrovos kelias, susisiekimas ir būtini barjerai.","Vienas asmuo turėtų parodyti kelią po kroviniu.","Krovinių gabenimui reikalingi saugūs eismo maršrutai ir aiškus koordinavimas."],"l2-schutzschlauch":["Į ką reikėtų atkreipti dėmesį naudojant stropus su apsaugine žarna?","Prie grubaus krašto guli juosta.","Bet koks plonas audinio audinys pakeičia tinkamą krašto apsaugą.","Apsauginė žarna pašalina bet kokią leistiną apkrovos ribą.","Pasirinkite apsaugines priemones pagal tinkamumo ir naudojimo reikalavimus.","Apsauginės priemonės turi atitikti medžiagą, kraštą ir numatomą apkrovą."],"l2-reinigung":["Kėlimo diržas buvo užterštas nežinoma chemine medžiaga. Kas yra teisinga?","Juostos nebegalima aiškiai įvertinti.","Nustokite naudoti ir profesionaliai išaiškinkite suderinamumą ar būklę.","Nuvalykite bet kokiu tirpikliu ir nedelsdami tęskite kėlimą.","Ignoruokite cheminę medžiagą, kol juosta yra sausa.","Cheminės medžiagos gali turėti įtakos tekstilinių stropų stiprumui."],"l2-aufhaengung":["Ką tikrinate, ar ant pakabos jungties nėra kelių sruogų?","Dvi sruogos dedamos kartu į suspensiją.","Sruogelė gali judėti į kabliuko galiuką savo nuožiūra.","Visi jungiamieji elementai turi būti tinkami ir išdėstyti taip, kaip numatyta.","Mažiems kroviniams galima naudoti žiedą su įtrūkimu.","Stabdymo ir jungiamieji elementai turi būti laikantys ir tinkamai išdėstyti."],"l2-einweiserrolle":["Kas taikoma, jei užpuolikas ir krano operatorius neturi matymo linijos?","Laikiklis blokuoja kritimo taško vaizdą.","Koordinuokite skambindami keliems žmonėms be atsakomybės.","Perkelkite apkrovą pagal triukšmą be nurodymų.","Organizuokite aiškų, saugų ryšį ir nutraukite jį, jei jis neaiškus.","Matomumo stoka turi būti kompensuojama efektyviu koordinavimu ir saugiu bendravimu."],"l2-ausserbetrieb":["Sugadintas stropas buvo sutvarkytas. Kas dar svarbu?","Jis lieka laisvai prieinamas kartu su paruoštais naudoti ištekliais.","Apsaugokite nuo tolesnio atsitiktinio naudojimo ir informuokite atsakingą asmenį.","Grąžinkite prekę be žymėjimo į inventorių.","Vėl naudokite tik veždami ypač lengvą krovinį.","Išmesti stropai prieš tolesnį naudojimą turi būti patikimai apsaugoti."],"b2-schwenkradius":["Kodėl ekskavatoriaus galinio svyravimo spindulys yra kritinis?","Uodega juda per ribotą darbo sritį.","Trečiuosius asmenis gali sugauti besisukantis antstatas.","Svyravimo spindulys neturi įtakos šalia mašinos esantiems žmonėms.","Galinė dalis visada juda tik važiavimo kryptimi.","Sukant pavojaus zona atsiranda ir už mašinos."],"b2-verkehrseinweiser":["Kaip užtikrinamas važiavimo judėjimas, kai matomumas yra užtemdytas?","Ekskavatorius turi manevruoti už kliūties.","Važiuokite nematydami signalizatoriaus signalų.","Jei reikia, suorganizuokite atitinkamą instruktažą aiškiai bendraujant.","Užtikrinkite važiavimą atbuline eiga tik vieną kartą paspaudę.","Painiai maršrutai reikalauja veiksmingų priemonių, kad būtų išvengta susidūrimų ir įstrigimo."],"b2-standplatz":["Kas taikoma ekskavatoriaus stovui ant šlaito?","Grindys nuožulnios ir gali būti slidžios.","Mašina gali išsitiesti tiek, kiek nori, esant bet kokiam nuolydžiui.","Visada pastatykite ekskavatorių ant puraus žemės sluoksnio.","Prieš naudodami patikrinkite mašinos stabilumą ir veikimo ribas.","Šlaito nuolydis ir podirvis turi didelę įtaką stabilumui."],"b2-oberleitung":["Kodėl reikia planuoti strėlės atstumą nuo elektros linijų?","Sukant strėlė gali priartėti prie troso.","Elektrinis blyksnis galimas ir be tiesioginio kontakto.","Elektrą gali pravesti tik kibiras, o ne strėlė.","Esant sausam dirvožemiui, kiekvienas atstumas yra automatiškai saugus.","Prieš artėjant prie elektros sistemų, būtina išsiaiškinti naudojimo ribas ir apsauginius atstumus."],"b2-fremdperson":["Praeivis įeina į statybvietę, esančią apsupimo zonoje. Kas yra teisinga?","Žmogus staiga atsistoja prie ekskavatoriaus kaušo.","Pakelkite kastuvą aukštyn ir pasukite jį virš žmogaus.","Nedelsdami sustabdykite judėjimą ir išvalykite vietą.","Tiesiog toliau stebėkite žmogų pro šoninį langą.","Pavojaus zonoje esantiems žmonėms darbo judesiai negali kelti pavojaus."],"b2-parkstellung":["Kaip apsaugoma žemės kasimo mašina baigus darbą?","Ekskavatorius statybvietėje lieka be priežiūros.","Palikite šaukštą galvos lygyje.","Leiskite varikliui veikti be priežiūros.","Nuleiskite darbo įrangą, pritvirtinkite mašiną ir apsaugokite nuo neteisėto naudojimo.","Tinkamas automobilio statymas sumažina atsitiktinį judėjimą ir neleistiną patekimą."],"b2-eigenlast":["Kodėl keliant ekskavatoriumi įrangos ribos yra labai svarbios?","Ant strėlės reikia pakelti didelį krovinį.","Priešingu atveju gali būti viršytas stabilumas ir leistina apkrova.","Bet kokia mašina gali pakelti bet kokį krovinį, kol telpa kaušas.","Tik stropo virvės ilgis lemia riziką.","Informacija apie keliamąją galią ir keliamąją galią priklauso nuo įrangos ir pritaikymo situacijos."],"b2-untergrundhohlraum":["Grindys virš seno rūsio gali būti tuščiavidurės. ka tu darai?","Turėtumėte nuvažiuoti ekskavatoriumi į teritoriją.","Pereikite vietą su maksimaliu greičiu.","Prieš važiuodami išsiaiškinkite keliamąją galią ir galimas ertmes.","Tiesiog uždėkite didelę apkrovą ant paviršiaus.","Dėl mašinos svorio ertmės gali įgriūti ir mašina sudužti."],"b2-feuchtigkeit":["Po stipraus lietaus pylimas tampa minkštas. Kas yra teisinga?","Netoli pylimo krašto dirba ekskavatorius.","Perkelkite mašiną arčiau krašto, kad padidintumėte pasiekiamumą.","Ignoruokite pakeitimus iki pamainos pabaigos.","Iš naujo įvertinti dirvožemio ir stabilumo sąlygas.","Drėgmės prasiskverbimas gali pakeisti pylimų laikomąją galią ir stabilumą."],"b2-bodenprobe":["Kodėl prieš kasant dujotiekio planus reikia patikrinti?","Kabeliai galėtų eiti po planuojamu kasinėjimu.","Kad būtų galima identifikuoti linijas ir suplanuoti tinkamas saugumo priemones.","Kad kasimas būtų atliktas greičiau, nepriklausomai nuo trečiųjų šalių sistemų.","Kadangi mašinos niekada neturi būti naudojamos šalia kabelių.","Prieš atliekant kasimo darbus požeminėms tiekimo linijoms reikia patikimai išsiaiškinti vietą."],"b2-maschinenzugang":["Kas taikoma įlipant ir išlipant iš žemės kasimo mašinos?","Mašina stovi ant nelygaus reljefo.","Iš kabinos ištraukite hidraulinę liniją žemyn.","Naudokite nurodytus žingsnius ir užtikrinkite saugų pagrindą.","Mašinai veikiant užšokkite ant pasukamos svirties.","Saugus lipimas ir tinkami sustojimo taškai sumažina kritimo ir suspaudimo riziką."],"b2-kupplung":["Kaip patikrinti naują ekskavatorių po montavimo?","Kaušas prijungiamas per greitąją jungtį.","Tik vizualiai vertinkite šaukštą iš didesnio atstumo.","Ženkite tiesiai po pakeltu šaukštu.","Užtikrinkite teisingą užrakinimą ir nurodytus valdymo veiksmus.","Neteisingai užrakinti priedai gali atsilaisvinti ir sukelti pavojų žmonėms."],"b2-hydraulikwartung":["Kodėl esant slėgiui neleidžiama atidaryti hidraulinių linijų?","Reikia pakeisti žarną.","Išbėgantis skystis dėl aukšto slėgio gali rimtai susižaloti.","Slėgis visada neleidžia alyvai išbėgti.","Atvirą liniją galima saugiai patikrinti rankomis.","Aukšto slėgio skystis gali prasiskverbti į audinius ir reikalauja saugaus slėgio mažinimo."],"b2-fahrweg":["Turite važiuoti per laikiną statybos tiltą. Ką tu tikrini?","Tiltas skirtas tik tam tikroms apkrovoms.","Ar tilto spalva atitinka mašiną.","Keliamoji galia ir tinkamumas mašinos svoriui ir matmenims.","Tik ar lengvas automobilis jau užvažiavo tiltu.","Laikinos konstrukcijos gali būti naudojamos tik neviršijant jų laikomosios galios."],"b2-baggertransport":["Kas svarbu gabenant ekskavatorių žemu krautuvu?","Mašina nuvežama į kitą statybvietę.","Leiskite darbo įrangai laisvai išsikišti per kraštą.","Važiuodami laikykite atidarytas salono duris.","Pritvirtinkite mašiną pagal transportavimo specifikacijas ir patikrinkite krovimo įrangą.","Transportavimo spynos ir tinkamos pakrovimo priemonės neleidžia paslysti ir nukristi."],"b2-schaufelfuellung":["Kodėl frontaliniam krautuvui neleidžiama greitai važiuoti aukštai pakeltu kaušu?","Krovinys sunkus, o žemė nelygi.","Aukštas svorio centras gali padidinti apvirtimo ir matomumo problemų riziką.","Kaušas automatiškai stabilizuojasi važiuojant dideliu greičiu.","Kastuvo aukštis neturi reikšmės stabilumui.","Pakeltas svorio centras paprastai pablogina stabilumą važiuojant ir posūkiuose."],"b2-fussgaenger":["Kaip elgiatės manevruodami šalia pėsčiųjų?","Prie statybų aikštelės privažiavimas taip pat yra pėsčiųjų takas.","Kastuvu nukreipkite pėsčiuosius į šoną.","Važiuokite tik tada, kai vieta yra saugiai laisva ir valdoma.","Tiesiog pagirkite vieną kartą ir važiuokite lėtai be matomumo.","Transporto priemonių ir keleivių eismas turi būti veiksmingai atskirtas arba saugiai koordinuojamas."],"b2-ueberlastwarnung":["Keliant mašina praneša apie perkrovą. ka tu darai?","Pakeltas krovinys pasiekia leistinas ribas.","Išjunkite įspėjimą ir toliau kelkite jį nepakeistą.","Staigiai priveržkite apkrovą, kol mašina veikia.","Sustabdykite pavojingus judesius ir saugiai ištaisykite krovinio padėtį.","Perspėjimai apie perkrovą rodo galimus apribojimų pažeidimus ir stabilumo riziką."],"b2-wasserleitung":["Kasant atidengtas nežinomas vamzdis. Kas taikoma?","Linija statybos planuose nepavaizduota.","Nutraukite darbą paveiktoje zonoje ir profesionaliai nustatykite liniją.","Pabandykite perkelti liniją ekskavatoriaus kastuvu.","Tęskite kasimą tiesiai po linija, netikrindami.","Nežinomos linijos gali sukelti elektros, dujų ar vandens pavojų."],"b2-hangefahrt":["Kaip vairuoti ekskavatorių stačiame šlaite?","Suplanuotas maršrutas veda šlaitu.","Važiuokite per šlaitą nepaisydami gamintojo apribojimų.","Laikykitės leistino mašinos nuolydžio ir nustatyto vairavimo stiliaus.","Pasukite strėlę toli, kad subalansuotumėte transporto priemonę.","Leistinas nuolydis priklauso nuo mašinos, paviršiaus ir gamintojo informacijos."],"b2-schlechtebeleuchtung":["Dirbant tamsioje duobėje matomumas yra nepakankamas. Kas yra teisinga?","Jūs beveik nematote žmonių ir kliūčių.","Padidinkite kasimo greitį, kad greitai užbaigtumėte operaciją.","Nenaudokite žibintų, kai variklis veikia.","Sustabdykite darbą, kol pavojaus zonos bus pakankamai matomos.","Norint valdyti mašinos judėjimą, būtinas saugus važiavimo ir darbo zonų matomumas."],"b2-kettenverschleiss":["Kasdieninės patikros metu pastebimas pažeistas vikšrų takelis. ka tu darai?","Grandininė jungtis rodo aiškų pažeidimą.","Nenaudokite mašinos toliau nekontroliuojamai ir praneškite apie bet kokią žalą.","Toliau važiuokite dideliu greičiu, kad grandinė išsitiesintų.","Tęskite darbą tik ant minkštos žemės, nepatikrindami.","Pavaros pažeidimas gali pabloginti valdymą ir stabilumą."],"b2-ladearbeiten":["Jūs pakraunate sunkvežimį su ekskavatoriumi. Kas svarbu?","Sunkvežimio vairuotojas lieka šalia pakrovimo vietos.","Pasukite kibirą virš neapsaugotos vairuotojo kabinos.","Neleiskite žmonėms likti pavojingoje zonoje ir koordinuokite procesus.","Pradėkite krovimą nesusisiekę su vairuotoju.","Pakrovimo metu kyla pavojus nukristi medžiagai ir siūbuoti."],"b2-arbeitsunterbrechung":["Pertraukiate kasimo darbus susitikimui. Kas taikoma?","Mašina turi stovėti kelias minutes nenaudojama.","Pakeltą kastuvą palikite kaip žymeklį.","Palikite mašiną be priežiūros su įjungta traukos pavara.","Saugiai pastatykite padargą ir apsaugokite mašiną nuo netyčinio naudojimo.","Net trumpiems pertraukimams reikalinga saugi mašinos būklė."],"b2-rollmaterial":["Transportuojant su ratiniu krautuvu gali nukristi palaida medžiaga. Kas yra teisinga?","Krautuvas važiuoja arti darbuotojų.","Saugiai paimkite krovinį ir pasirinkite saugų vairavimo stilių su tinkama kastuvo padėtimi.","Pakelkite kastuvą kuo aukščiau, kad aplinkui būtų aiškus vaizdas.","Paimkite krovinį neribodami kaušo užpildymo.","Laisvas krovinys, aukšta kaušo padėtis ir blogas matomumas gali kelti pavojų žmonėms ir eismui."]};
